INSERT INTO practice_sets (title,description,skill,scope,metadata_json,status,created_by,creation_method) VALUES
    ('Premium TOPIK 35 · Đọc 50 câu', 'Bộ Đọc 50 câu đầy đủ; experimental practice, không phải kỳ thi chính thức.', 'READING', 'GLOBAL', JSON_OBJECT('seedBundle',@topik35_bundle,'seedKey','topik35-reading','premium',TRUE,'releaseScope','EXPERIMENTAL_DEMO','questionCount',50), 'PUBLISHED', @topik35_author, 'CANONICAL_SEED'),
    ('Premium TOPIK 35 · Nghe 50 câu liên tục', 'Bộ Nghe 50 câu với một chương trình audio liên tục; chỉ phát một lần trong test.', 'LISTENING', 'GLOBAL', JSON_OBJECT('seedBundle',@topik35_bundle,'seedKey','topik35-listening','premium',TRUE,'releaseScope','EXPERIMENTAL_DEMO','questionCount',50,'continuousPlayback',TRUE,'startOnce',TRUE), 'PUBLISHED', @topik35_author, 'CANONICAL_SEED'),
    ('Premium TOPIK 35 · Viết Q51–Q54', 'Bộ Viết đủ Q51, Q52, Q53 và Q54; feedback AI chỉ mang tính thử nghiệm.', 'WRITING', 'GLOBAL', JSON_OBJECT('seedBundle',@topik35_bundle,'seedKey','topik35-writing','premium',TRUE,'releaseScope','EXPERIMENTAL_DEMO','questionCount',4), 'PUBLISHED', @topik35_author, 'CANONICAL_SEED');
