INSERT INTO practice_sections (set_id,test_id,title,skill,section_type,instructions,delivery_json,duration_minutes,total_points,display_order) VALUES
    (@rset,@rtest,'Phần Đọc','READING','MAIN','Hoàn thành 50 câu Đọc.',NULL,70,100,0),
    (@lset,@ltest,'Phần Nghe','LISTENING','MAIN','Audio chạy liên tục một lần; không tua hoặc phát lại.',CAST('{"schemaVersion":"practice-section-delivery-v1","listeningDelivery":{"checkAudioReference":"/audio/practice/listening-speaker-check.wav","programAudioReference":"/audio/practice/topik35/1631e1e081a1b90d6aa77c6d87d1ee15f83346c6b7d2eaa3a0f6adfc590bfaa6.mp3","startOnce":true,"continuousPlayback":true,"seekAllowed":false,"replayAllowed":false}}' AS JSON),60,100,0),
    (@wset,@wtest,'Phần Viết','WRITING','MAIN','Hoàn thành Q51–Q54. Feedback AI là thử nghiệm.',NULL,50,100,0);
INSERT INTO practice_question_groups (set_id,section_id,group_label,question_from,question_to,instruction,stimulus_type,instruction_language_tag,stimulus_language_tag,passage_text,transcript_text,image_url,stimulus_provenance_json,audio_url,example_json,display_order) VALUES
    (@rset, @rsec, 'R001', 1, 1, '빈칸에 들어갈 가장 알맞은 것을 고르십시오.', 'READING_PASSAGE', 'ko', 'ko', '어제는 친구들과 같이 점심을 [BLANK] 바로 도서관에 갔다.', NULL, NULL, CAST('{"source":"TOPIK35_REPO_PACKAGE","qaStatus":"VISUALLY_VERIFIED"}' AS JSON), NULL, NULL, 0),
    (@rset, @rsec, 'R002', 2, 2, '빈칸에 들어갈 가장 알맞은 것을 고르십시오.', 'READING_PASSAGE', 'ko', 'ko', '이사 갈 집을 [BLANK] 방학 때 좀 바빴다.', NULL, NULL, CAST('{"source":"TOPIK35_REPO_PACKAGE","qaStatus":"VISUALLY_VERIFIED"}' AS JSON), NULL, NULL, 1),
    (@rset, @rsec, 'R003', 3, 3, '밑줄 친 부분과 의미가 비슷한 것을 고르십시오.', 'READING_PASSAGE', 'ko', 'ko', '어제 본 공연은 눈물이 날 정도로 감동적이었다.', NULL, NULL, CAST('{"source":"TOPIK35_REPO_PACKAGE","qaStatus":"VISUALLY_VERIFIED"}' AS JSON), NULL, NULL, 2),
    (@rset, @rsec, 'R004', 4, 4, '밑줄 친 부분과 의미가 비슷한 것을 고르십시오.', 'READING_PASSAGE', 'ko', 'ko', '두 사람은 오랫동안 알고 지냈지만 직장 동료 사이일 뿐이다.', NULL, NULL, CAST('{"source":"TOPIK35_REPO_PACKAGE","qaStatus":"VISUALLY_VERIFIED"}' AS JSON), NULL, NULL, 3),
    (@rset, @rsec, 'R005', 5, 5, '무엇에 대한 글인지 고르십시오.', 'READING_PASSAGE', 'ko', 'ko', '날마다 새로운 세상을 읽는다. 세상을 보는 눈!', NULL, NULL, CAST('{"source":"TOPIK35_REPO_PACKAGE","qaStatus":"VISUALLY_VERIFIED"}' AS JSON), NULL, NULL, 4),
    (@rset, @rsec, 'R006', 6, 6, '무엇에 대한 글인지 고르십시오.', 'READING_PASSAGE', 'ko', 'ko', '아프세요? 참지 마세요. 상담부터 수술까지 친절하게 도와 드리겠습니다.', NULL, NULL, CAST('{"source":"TOPIK35_REPO_PACKAGE","qaStatus":"VISUALLY_VERIFIED"}' AS JSON), NULL, NULL, 5),
    (@rset, @rsec, 'R007', 7, 7, '무엇에 대한 글인지 고르십시오.', 'READING_PASSAGE', 'ko', 'ko', '숲에서 부는 시원한 바람. 숲에서 사는 귀여운 동물. 숲이 없어지면 이 모든 것이 없어집니다.', NULL, NULL, CAST('{"source":"TOPIK35_REPO_PACKAGE","qaStatus":"VISUALLY_VERIFIED"}' AS JSON), NULL, NULL, 6),
    (@rset, @rsec, 'R008', 8, 8, '무엇에 대한 글인지 고르십시오.', 'READING_PASSAGE', 'ko', 'ko', '궁금하신 점은 서울화장품 홈페이지 고객 게시판에 남겨 주십시오. 상담원과 통화를 원하시면 080-987-6543으로 전화해 주십시오.', NULL, NULL, CAST('{"source":"TOPIK35_REPO_PACKAGE","qaStatus":"VISUALLY_VERIFIED"}' AS JSON), NULL, NULL, 7),
    (@rset, @rsec, 'R009', 9, 9, '도표의 내용과 같은 것을 고르십시오.', 'READING_PASSAGE', 'ko', 'ko', '제10회 서울국제꽃박람회. 입장료: 일반 9,000원, 단체(20인 이상) 7,000원, 특별권 10,000원. 단체 요금은 평일에만 가능하다. 특별권 구입 시 행사장 내 놀이 시설을 무료로 이용할 수 있다. 대중교통 이용자는 입장료 1,000원을 할인받는다.', NULL, '/images/practice/topik35/4cb2443e992e0b2995454cf255d1c88b47ea2fd322ca877e5fe453538c17b040.png', CAST('{"source":"TOPIK35_REPO_PACKAGE","qaStatus":"VISUALLY_VERIFIED"}' AS JSON), NULL, NULL, 8),
    (@rset, @rsec, 'R010', 10, 10, '도표의 내용과 같은 것을 고르십시오.', 'READING_PASSAGE', 'ko', 'ko', '애완동물을 어디에서 구하셨습니까? 아는 사람 39.3%, 애완동물 가게 36.7%, 인터넷 16.8%, 버려진 동물 7.2%.', NULL, '/images/practice/topik35/c2d68824c64b2af44591a70d17939d3a2fb986a8f41ba70353b261ee6b34790d.png', CAST('{"source":"TOPIK35_REPO_PACKAGE","qaStatus":"VISUALLY_VERIFIED"}' AS JSON), NULL, NULL, 9),
    (@rset, @rsec, 'R011', 11, 11, '글의 내용과 같은 것을 고르십시오.', 'READING_PASSAGE', 'ko', 'ko', '최근 70~80년대를 경험해 볼 수 있는 문화 공간이 생겼다. 서울시에서 새로 문을 연 ‘추억극장’이 바로 그곳이다. 입장료 2,000원만 내면 남녀노소 누구나 그때 유행했던 영화를 관람할 수 있으며 커피와 차, 과자 등 간단한 간식도 먹을 수 있다. 극장 내부에는 추억의 영화 포스터, 영화표 등이 전시되어 있다.', NULL, NULL, CAST('{"source":"TOPIK35_REPO_PACKAGE","qaStatus":"VISUALLY_VERIFIED"}' AS JSON), NULL, NULL, 10),
    (@rset, @rsec, 'R012', 12, 12, '글의 내용과 같은 것을 고르십시오.', 'READING_PASSAGE', 'ko', 'ko', '사람들은 가끔씩 지금과는 다른 내가 되고 싶어 한다. 이런 마음은 가면을 통해서 나타낼 수 있는데 가면을 쓰면 잠시 동안이지만 현실과 다른 나를 표현할 수 있다. 예를 들어 힘이 약한 사람이 호랑이 가면을 쓰게 되면 호랑이처럼 힘이 세다고 생각한다. 그래서 정말 힘센 사람처럼 행동하게 되고 이를 통해 스스로 만족하게 된다.', NULL, NULL, CAST('{"source":"TOPIK35_REPO_PACKAGE","qaStatus":"VISUALLY_VERIFIED"}' AS JSON), NULL, NULL, 11),
    (@rset, @rsec, 'R013', 13, 13, '문장을 순서대로 맞게 배열한 것을 고르십시오.', 'READING_PASSAGE', 'ko', 'ko', '(가) 또한 재료 가격이 싸서 제작 비용도 적게 든다. (나) 그중 하나가 운동선수들의 유니폼을 만드는 것이다. (다) 플라스틱 병을 재활용하는 방법에는 여러 가지가 있다. (라) 플라스틱 병을 소재로 해서 운동복을 만들면 가볍고 시원하다.', NULL, NULL, CAST('{"source":"TOPIK35_REPO_PACKAGE","qaStatus":"VISUALLY_VERIFIED"}' AS JSON), NULL, NULL, 12),
    (@rset, @rsec, 'R014', 14, 14, '문장을 순서대로 맞게 배열한 것을 고르십시오.', 'READING_PASSAGE', 'ko', 'ko', '(가) 그러자 남자는 다른 쪽 신발도 벗어 그 옆으로 떨어뜨렸다. (나) 남자가 신발을 주우려고 했지만 기차가 움직이기 시작했다. (다) 신발의 짝이 맞아야 누군가 신을 수 있다고 생각했기 때문이었다. (라) 남자가 기차에 타려는 순간 신발 한 짝이 벗겨져 아래로 떨어졌다.', NULL, NULL, CAST('{"source":"TOPIK35_REPO_PACKAGE","qaStatus":"VISUALLY_VERIFIED"}' AS JSON), NULL, NULL, 13),
    (@rset, @rsec, 'R015', 15, 15, '문장을 순서대로 맞게 배열한 것을 고르십시오.', 'READING_PASSAGE', 'ko', 'ko', '(가) 희망택시 지원 사업은 버스 운행에 비해 훨씬 적은 예산이 든다. (나) 그러므로 택시 요금을 지원하더라도 정부는 예산을 아낄 수 있다. (다) 이 택시의 이용 요금은 1,100원이고 추가 요금은 정부에서 부담한다. (라) 버스가 다니지 않는 시골 마을에 주민들을 위한 희망택시가 등장했다.', NULL, NULL, CAST('{"source":"TOPIK35_REPO_PACKAGE","qaStatus":"VISUALLY_VERIFIED"}' AS JSON), NULL, NULL, 14),
    (@rset, @rsec, 'R016', 16, 16, '빈칸에 들어갈 내용으로 가장 알맞은 것을 고르십시오.', 'READING_PASSAGE', 'ko', 'ko', '사람들은 다양한 상황에서 스트레스를 받는다. 특히 업무가 많고 복잡한 인간관계로 얽힌 회사에서 스트레스를 많이 받는다. 그런데 기혼 직장 여성의 경우 [BLANK] 스트레스를 더 받는 것으로 나타났다. 그 이유는 여성이 느끼는 가사와 육아에 대한 부담이 여전히 크기 때문이다.', NULL, NULL, CAST('{"source":"TOPIK35_REPO_PACKAGE","qaStatus":"VISUALLY_VERIFIED"}' AS JSON), NULL, NULL, 15),
    (@rset, @rsec, 'R017', 17, 17, '빈칸에 들어갈 내용으로 가장 알맞은 것을 고르십시오.', 'READING_PASSAGE', 'ko', 'ko', '추석에는 환하고 둥근 보름달이 뜬다. 그런데 추석 때 먹는 송편은 보름달이 아닌 반달 모양이다. 이는 반달이 현재보다 더 나은 미래를 의미하기 때문이다. 즉 보름달은 밝고 완전한 모양이지만 시간이 지나면서 점점 작아지는 데 반해, 반달은 [BLANK]. 이처럼 송편의 반달 모양에는 앞으로 모든 일이 발전해 나가기를 바라는 희망이 담겨 있다.', NULL, NULL, CAST('{"source":"TOPIK35_REPO_PACKAGE","qaStatus":"VISUALLY_VERIFIED"}' AS JSON), NULL, NULL, 16),
    (@rset, @rsec, 'R018', 18, 18, '빈칸에 들어갈 내용으로 가장 알맞은 것을 고르십시오.', 'READING_PASSAGE', 'ko', 'ko', '이제 음식을 빨리 먹어서 소화가 잘 안되는 문제를 쉽게 해결할 수 있게 되었다. 왜냐하면 식사 속도를 조절해 주는 포크가 개발되었기 때문이다. 이 포크는 1분당 입 안에 들어가는 횟수로 먹는 속도를 측정한다. 그래서 식사 속도가 빠르면 포크에서 경고음이 난다. 앞으로 이 포크는 [BLANK] 데 도움을 줄 것으로 보인다.', NULL, NULL, CAST('{"source":"TOPIK35_REPO_PACKAGE","qaStatus":"VISUALLY_VERIFIED"}' AS JSON), NULL, NULL, 17),
    (@rset, @rsec, 'R019_020', 19, 20, '글을 읽고 두 물음에 답하십시오.', 'READING_PASSAGE', 'ko', 'ko', '과일을 빨리 익히기 위해 화학 물질이 사용되기도 한다. 그러나 화학 물질로 익힌 과일은 겉은 익었지만 속이 잘 익지 않은 경우가 많다. 그래서 화학 물질로 익힌 과일은 대개 자연적으로 숙성된 과일에 비해 맛과 향이 떨어진다. [BLANK] 화학 물질이 과일 껍질에 남게 될 수도 있다. 이런 과일을 지속적으로 먹으면 건강에 문제가 생기게 된다.', NULL, NULL, CAST('{"source":"TOPIK35_REPO_PACKAGE","qaStatus":"VISUALLY_VERIFIED"}' AS JSON), NULL, NULL, 18),
    (@rset, @rsec, 'R021_022', 21, 22, '글을 읽고 두 물음에 답하십시오.', 'READING_PASSAGE', 'ko', 'ko', '사람들은 보통 선택을 할 때 여러 가지 중에서 고르면 더 좋은 선택을 할 수 있을 것이라고 생각한다. 그래서 선택이 필요할 때 정보를 많이 수집하려고 노력한다. 그러나 선택의 수가 늘어나면 고민의 양도 함께 증가한다. [BLANK] 결정을 내리지 못하는 상황이 되는 것이다. 후회 없는 선택을 위한 노력이 오히려 선택을 방해하는 결과를 불러오게 된다.', NULL, NULL, CAST('{"source":"TOPIK35_REPO_PACKAGE","qaStatus":"VISUALLY_VERIFIED"}' AS JSON), NULL, NULL, 19),
    (@rset, @rsec, 'R023_024', 23, 24, '글을 읽고 두 물음에 답하십시오.', 'READING_PASSAGE', 'ko', 'ko', '내가 운영하는 회사의 사정이 점점 더 어려워졌다. 공장에 불이 나서 피해를 입은 데다가 매출까지 크게 감소한 것이다. 어쩔 수 없이 직원 수를 줄여야 했다. 나는 직원들을 한자리에 불러 모아 놓고도 한참을 아무 말도 할 수 없었다. 눈을 지그시 감고 겨우 입을 떼려는 순간 “사장님!” 한 직원이 나를 불렀다. 그 직원은 흰 봉투를 내 앞으로 내밀면서 말했다. “그동안 어려운 회사 살림 때문에 고생 많으셨습니다. 어려워진 회사에 도움이 될까 싶어서 저희들이 월급의 10퍼센트씩을 모았습니다. 적은 돈이지만 회사 운영에 도움이 되었으면 합니다.” 순간 나는 마치 천하를 얻은 듯 마음이 든든해졌다.', NULL, NULL, CAST('{"source":"TOPIK35_REPO_PACKAGE","qaStatus":"VISUALLY_VERIFIED"}' AS JSON), NULL, NULL, 20),
    (@rset, @rsec, 'R025', 25, 25, '신문 기사 제목을 가장 잘 설명한 것을 고르십시오.', 'READING_PASSAGE', 'ko', 'ko', '한쪽으로 메는 가방, 허리 건강 ‘빨간 불’', NULL, NULL, CAST('{"source":"TOPIK35_REPO_PACKAGE","qaStatus":"VISUALLY_VERIFIED"}' AS JSON), NULL, NULL, 21),
    (@rset, @rsec, 'R026', 26, 26, '신문 기사 제목을 가장 잘 설명한 것을 고르십시오.', 'READING_PASSAGE', 'ko', 'ko', '독특한 모양의 간판, 지나가는 사람들의 시선 끌어', NULL, NULL, CAST('{"source":"TOPIK35_REPO_PACKAGE","qaStatus":"VISUALLY_VERIFIED"}' AS JSON), NULL, NULL, 22),
    (@rset, @rsec, 'R027', 27, 27, '신문 기사 제목을 가장 잘 설명한 것을 고르십시오.', 'READING_PASSAGE', 'ko', 'ko', '취업률 석 달째 제자리걸음, 정부의 현실적인 대책 필요해', NULL, NULL, CAST('{"source":"TOPIK35_REPO_PACKAGE","qaStatus":"VISUALLY_VERIFIED"}' AS JSON), NULL, NULL, 23),
    (@rset, @rsec, 'R028', 28, 28, '빈칸에 들어갈 내용으로 가장 알맞은 것을 고르십시오.', 'READING_PASSAGE', 'ko', 'ko', '새를 상자 안에 넣으면 자꾸 밖으로 나오려고 한다. 그러나 반대로 자유로운 공간에서는 안정을 찾고 도망치려고 애쓰지 않는다. 아이도 이와 마찬가지다. 부모들이 [BLANK] 하면 아이는 이를 구속이라 생각하고 반발심을 가진다. 그러나 일어나는 시간, 방과 후 할 일 등 생활 규칙을 아이와 의논하여 정하게 되면 부모가 시키지 않아도 스스로 책임감을 가지고 잘 지키려고 노력한다.', NULL, NULL, CAST('{"source":"TOPIK35_REPO_PACKAGE","qaStatus":"VISUALLY_VERIFIED"}' AS JSON), NULL, NULL, 24),
    (@rset, @rsec, 'R029', 29, 29, '빈칸에 들어갈 내용으로 가장 알맞은 것을 고르십시오.', 'READING_PASSAGE', 'ko', 'ko', '사람들은 문화생활을 위한 시간을 따로 내기가 어렵다고들 한다. 최근 이런 사람들을 위해 [BLANK] 새로운 문화 콘텐츠들이 등장하고 있다. 그중 하나가 웹 소설인데 이것은 5분 이내에 읽을 수 있는 짧은 분량의 인터넷 소설을 말한다. 이 소설은 컴퓨터 화면에서 읽어도 눈이 피로하지 않도록 줄 간격이 넓게 편집되어 있다. 그리고 소설의 내용을 쉽게 이해할 수 있도록 등장인물의 수를 제한하는 것도 특징이다.', NULL, NULL, CAST('{"source":"TOPIK35_REPO_PACKAGE","qaStatus":"VISUALLY_VERIFIED"}' AS JSON), NULL, NULL, 25),
    (@rset, @rsec, 'R030', 30, 30, '빈칸에 들어갈 내용으로 가장 알맞은 것을 고르십시오.', 'READING_PASSAGE', 'ko', 'ko', '조선 시대에는 큰 명절이나 나라에 축하할 일이 생겼을 때 궁중에서 잔치를 열었다. 보통 잔치를 할 때에는 맛있고 귀한 음식을 가득 차려 놓고 성대하게 행사를 치렀다. 그러나 이 음식들은 잔치에 참석한 왕과 높은 지위의 일부 사람들만을 위한 것은 아니었다. 잔치가 끝난 뒤 가난한 백성들에게 나누어 주기 위해 일부러 많은 음식을 준비했던 것이다. 잔치를 통해 [BLANK] 의도에서였다.', NULL, NULL, CAST('{"source":"TOPIK35_REPO_PACKAGE","qaStatus":"VISUALLY_VERIFIED"}' AS JSON), NULL, NULL, 26),
    (@rset, @rsec, 'R031', 31, 31, '빈칸에 들어갈 내용으로 가장 알맞은 것을 고르십시오.', 'READING_PASSAGE', 'ko', 'ko', '최근에는 미술 작품을 과학적 연구의 참고 자료로 활용하고 있다. 그중 하나가 풍경화에 사용된 색을 연구하여 그 시대의 대기 상태를 알아보는 것이다. 일반적으로 공기 중에 먼지가 많으면 해가 질 때 하늘은 더 붉게 보인다고 한다. 그런데 산업화가 진행된 20세기 말 그림 속에 표현된 하늘이 다른 시대의 그림보다 더 붉다. 우리는 그 그림을 통해 20세기 말에 [BLANK] 사실을 확인할 수 있다.', NULL, NULL, CAST('{"source":"TOPIK35_REPO_PACKAGE","qaStatus":"VISUALLY_VERIFIED"}' AS JSON), NULL, NULL, 27),
    (@rset, @rsec, 'R032', 32, 32, '글의 내용과 같은 것을 고르십시오.', 'READING_PASSAGE', 'ko', 'ko', '항공사들은 비행기 안에서 먹는 기내식의 맛을 살리기 위해 많은 노력을 한다. 먼저 건조한 기내 환경을 고려하여 음식의 수분이 날아가지 않도록 포장에 신경을 쓴다. 또한 고도가 높아졌을 때 사람들의 미각이 둔해지는 것에 대비해서 일부러 음식을 조금 짜게 만든다. 또 기내식은 미리 조리하여 냉동한 후 비행기에 싣기 때문에 손님들에게 내놓기 직전에 다시 따뜻하게 데운다.', NULL, NULL, CAST('{"source":"TOPIK35_REPO_PACKAGE","qaStatus":"VISUALLY_VERIFIED"}' AS JSON), NULL, NULL, 28),
    (@rset, @rsec, 'R033', 33, 33, '글의 내용과 같은 것을 고르십시오.', 'READING_PASSAGE', 'ko', 'ko', '요즘 도시에 벌의 수가 증가하여 이로 인한 피해가 종종 발생하고 있다. 한 연구팀은 도시가 벌이 살기에 적합한 환경이 된 것이 원인이라고 밝혔다. 도시 환경이 벌의 생존에 도움이 된다는 것이다. 도시의 공원에서 다양한 꽃과 식물이 자라고 있어 풍부한 먹이를 제공한다고 한다. 농촌에 비해 도시가 상대적으로 농약 사용이 적어 안전하다는 것도 도시에 벌이 많아진 또 하나의 이유라고 한다.', NULL, NULL, CAST('{"source":"TOPIK35_REPO_PACKAGE","qaStatus":"VISUALLY_VERIFIED"}' AS JSON), NULL, NULL, 29),
    (@rset, @rsec, 'R034', 34, 34, '글의 내용과 같은 것을 고르십시오.', 'READING_PASSAGE', 'ko', 'ko', '정부에서 ‘휴가 하루 더 가기’ 캠페인을 벌이고 있다. 국내 관광의 활성화를 목적으로 기업들과 근로자의 참여를 유도하겠다는 것이다. 국민들의 국내 휴가 일수가 하루 증가하면 소비가 2조 5천 억 원이 늘어 경제가 활성화된다. 또 관광업계에 5만 개 이상의 일자리가 생길 것으로 예상된다. 집중력이 떨어질 수 있는 더운 여름철, 근로자들의 사기를 높이는 데에도 도움이 될 것으로 보인다.', NULL, NULL, CAST('{"source":"TOPIK35_REPO_PACKAGE","qaStatus":"VISUALLY_VERIFIED"}' AS JSON), NULL, NULL, 30),
    (@rset, @rsec, 'R035', 35, 35, '글의 주제로 가장 알맞은 것을 고르십시오.', 'READING_PASSAGE', 'ko', 'ko', '미혼이라는 말에는 결혼은 꼭 해야 하는 것이지만 아직 하지 않았다는 뜻이 포함되어 있다. 그러나 결혼은 필수가 아니라 선택이라고 생각하는 사람들이 증가함에 따라 미혼이라는 말 대신에 결혼을 선택하지 않는다는 의미의 비혼이라는 단어가 사용되기 시작하였다. 미혼, 독신 등의 단어들이 비혼이라는 단어에 자리를 내주게 된 것이다.', NULL, NULL, CAST('{"source":"TOPIK35_REPO_PACKAGE","qaStatus":"VISUALLY_VERIFIED"}' AS JSON), NULL, NULL, 31),
    (@rset, @rsec, 'R036', 36, 36, '글의 주제로 가장 알맞은 것을 고르십시오.', 'READING_PASSAGE', 'ko', 'ko', '패션도 비즈니스의 일부이다. 비즈니스를 목적으로 누군가를 만나야 한다면 비즈니스 상황에 따라 입고 나갈 옷의 색상, 디자인, 소재 등을 고려하여 전략적으로 이미지를 연출하는 것이 중요하다. 강한 의지를 표명해야 한다면 빳빳한 소재의 무채색 옷을 선택하는 것이 바람직하다. 반면에 상대 회사와 협상을 해야 한다면 광택이 있는 부드러운 소재의 복장을 통해 편안한 분위기를 연출하는 것이 좋다. 상대 회사를 상징하는 색상의 셔츠나 넥타이로 친근감을 표현할 수도 있다.', NULL, NULL, CAST('{"source":"TOPIK35_REPO_PACKAGE","qaStatus":"VISUALLY_VERIFIED"}' AS JSON), NULL, NULL, 32),
    (@rset, @rsec, 'R037', 37, 37, '글의 주제로 가장 알맞은 것을 고르십시오.', 'READING_PASSAGE', 'ko', 'ko', '육체적·정신적 피로로 인해 무기력한 상태가 지속된다면 소진증후군을 의심해 보아야 한다. 이 증후군의 대표적인 증상으로는 심한 불안감, 무기력, 삶에 대한 무관심 등을 들 수 있다. 일단 소진증후군을 앓게 되면 회복이 힘들다는 점을 고려할 때 휴식과 재충전을 통해 심신의 건강을 유지하려는 자세가 요구된다. 평소 작은 일에 기뻐하고 행복해 함으로써 삶의 활력을 유지하는 것도 이 증후군을 예방하는 데 도움이 된다.', NULL, NULL, CAST('{"source":"TOPIK35_REPO_PACKAGE","qaStatus":"VISUALLY_VERIFIED"}' AS JSON), NULL, NULL, 33),
    (@rset, @rsec, 'R038', 38, 38, '글의 주제로 가장 알맞은 것을 고르십시오.', 'READING_PASSAGE', 'ko', 'ko', '그동안 로봇이 주로 인간의 육체노동만을 대체해 왔다면 앞으로는 지식 노동까지도 대체하게 될 것이다. 이러한 로봇의 등장으로 사람들은 일자리를 잃게 될지도 모른다는 생각을 할 수도 있다. 그러나 남는 노동 자원을 로봇이 대체할 수 없는 일에 활용할 수 있다는 긍정적인 면도 있다. 예를 들어 기업의 실적이나 스포츠 경기의 결과에 대한 데이터 수집이나 분석과 같은 단순 업무는 ‘로봇기자’가 담당하고 기자들은 심층 분석이나 인터뷰와 같은 깊이 있는 기사 작성에 더 집중할 수 있게 될 것이다.', NULL, NULL, CAST('{"source":"TOPIK35_REPO_PACKAGE","qaStatus":"VISUALLY_VERIFIED"}' AS JSON), NULL, NULL, 34),
    (@rset, @rsec, 'R039', 39, 39, '보기 문장이 들어가기에 가장 알맞은 곳을 고르십시오.', 'READING_PASSAGE', 'ko', 'ko', '운전 시 안전과 직결되는 것 중의 하나가 바로 차선이다. [SLOT_1] 야간 운전 중에 차선이 잘 보이지 않으면 크고 작은 사고들이 발생하게 될 것이다. [SLOT_2] 반사 성능을 더욱 강화하고자 할 때에는 유리알이 혼합된 페인트를 사용할 수 있다. [SLOT_3] 이렇게 하면 유리알이 불빛에 반사되어 차선이 더욱 잘 보이게 된다. [SLOT_4]', NULL, NULL, CAST('{"source":"TOPIK35_REPO_PACKAGE","qaStatus":"VISUALLY_VERIFIED"}' AS JSON), NULL, NULL, 35),
    (@rset, @rsec, 'R040', 40, 40, '보기 문장이 들어가기에 가장 알맞은 곳을 고르십시오.', 'READING_PASSAGE', 'ko', 'ko', '부자들을 대상으로 사업체 상속 계획에 대해 조사한 결과 부의 축적 유형에 따라 차이를 보였다. [SLOT_1] 상속형 부자의 경우 절반 정도가 사업체를 자녀에게 물려주겠다고 응답했다. [SLOT_2] 반면 자수성가형 부자는 자녀 상속 의향이 20% 정도에 지나지 않았다. [SLOT_3] 상속형 부자는 자녀에게 기회를 주기 위해 물려준다고 응답한 반면 자수성가형 부자는 기술 및 비법 등을 전수하기 위해서 물려준다고 답했다. [SLOT_4]', NULL, NULL, CAST('{"source":"TOPIK35_REPO_PACKAGE","qaStatus":"VISUALLY_VERIFIED"}' AS JSON), NULL, NULL, 36),
    (@rset, @rsec, 'R041', 41, 41, '보기 문장이 들어가기에 가장 알맞은 곳을 고르십시오.', 'READING_PASSAGE', 'ko', 'ko', '지난 10년간 ‘한국형 리더십’에 남다른 관심을 쏟아 온 박선호 박사는 『세종에게서 배우다』라는 신간을 내놓았다. [SLOT_1] 『세종에게서 배우다』는 세종의 리더십을 배워 잘 활용할 수 있도록 돕는 일종의 경영서이다. [SLOT_2] 세종은 여러 분야에서 리더로서의 면모를 보여 주었다. 만일 그에게 탁월한 리더십이 없었더라면 한글 창제와 같은 업적은 불가능했을지도 모른다. [SLOT_3] 신분이나 지역을 따지지 않고 오직 개인의 역량만을 기준으로 사람을 뽑아 썼다. [SLOT_4]', NULL, NULL, CAST('{"source":"TOPIK35_REPO_PACKAGE","qaStatus":"VISUALLY_VERIFIED"}' AS JSON), NULL, NULL, 37),
    (@rset, @rsec, 'R042_043', 42, 43, '글을 읽고 두 물음에 답하십시오.', 'READING_PASSAGE', 'ko', 'ko', '초등학교 3학년쯤으로 보이는 남자 아이가 가장 높은 다이빙대에 올라갔다. 성인도 호기로 올라갔다가 그냥 내려오곤 하는 곳이었다. 소년은 무서워서 뛰어내리지도, 뒤돌아 내려가지도 못하고 다이빙대 끝과 계단 사이를 한참 왔다 갔다 했다. 그러자 부모로 보이는 사람이 내려오라는 손짓을 했다. 아이는 계속 망설였다. 수영장의 모든 사람이 이 모습을 지켜보고 있었다. 그때였다. 스피커에서 수영장 관리자로 추정되는 사람의 목소리가 나오기 시작했다. 나는 당연히 아이의 부모에게 ‘어서 아이를 데리고 내려오라.’고 말할 줄 알았다. 그런데 그는 전혀 다른 말을 했다. “넌 할 수 있어! 내가 도와줄게. 이제 셋을 셀 거야. 겁내지 말고 뛰어내리면 돼!” 그리고 큰 소리로 숫자를 세기 시작했다. 수영장에 있던 모든 사람도 스피커 소리를 따라 큰 소리로 숫자를 따라 셌다. (중략) 아이는 다이빙대 끝을 박차고 허공에 손을 휘저으며 뛰어내렸다. 아이가 물로 떨어지는 몇 초 동안, 모든 것은 잠시 숨을 멈추었다. 바람도 공기도 나뭇잎의 흔들림까지. 이윽고 ‘풍덩’ 하는 소리와 함께 세상은 다시 깨어났다. 박수 소리가 수영장을 울렸다. 나도 손뿐 아니라 마음 깊은 곳에서 박수를 보냈다.', NULL, NULL, CAST('{"source":"TOPIK35_REPO_PACKAGE","qaStatus":"VISUALLY_VERIFIED"}' AS JSON), NULL, NULL, 38),
    (@rset, @rsec, 'R044_045', 44, 45, '글을 읽고 두 물음에 답하십시오.', 'READING_PASSAGE', 'ko', 'ko', '환경부는 ‘온실가스 배출권 거래제’의 시행을 앞두고 향후 3년간 온실가스 총량을 정해 업종별로 할당한다는 계획을 발표했다. 이 제도는 지구온난화의 원인인 온실가스를 줄이기 위한 것으로 업체별로 일정한 배출량을 정해 놓고 기준보다 많거나 모자라는 경우 배출권을 사고팔 수 있게 하는 제도이다. 그런데 기업의 성장률을 고려하지 않고 할당량을 정하는 방식에 대해 문제가 있다는 지적이 있다. [BLANK] 기업은 배출권을 구입해야 하는데 경영 악화로 공장을 가동하지 않는 기업은 도리어 배출권 판매 이익을 취할 수 있기 때문이다. 새 제도의 정착을 위해 모두가 납득할 수 있는 합리적인 시행 방안이 마련되어야 할 것이다.', NULL, NULL, CAST('{"source":"TOPIK35_REPO_PACKAGE","qaStatus":"VISUALLY_VERIFIED"}' AS JSON), NULL, NULL, 39),
    (@rset, @rsec, 'R046_047', 46, 47, '글을 읽고 두 물음에 답하십시오.', 'READING_PASSAGE', 'ko', 'ko', '만년 2위를 면하지 못하던 포털 사이트 ‘둠’과 모바일 서비스 시장의 떠오르는 샛별 ‘코코’가 합병을 결정하면서 IT 업계의 지각 변동이 예고된다. 이를 두고 재계의 예측은 양분된다. [SLOT_1] 그 하나는 둠의 콘텐츠와 코코의 서비스 경쟁력이 결합했을 때 최상의 시너지 효과를 발휘할 것이라고 보는 입장이다. [SLOT_2] 다른 하나는 현재보다 그 역량이 줄어들 것이라고 보는 입장이다. [SLOT_3] 혼자서 하는 일에는 최선을 다하던 사람도 공동 작업에서는 그렇지 않을 수 있기 때문이다. [SLOT_4] 여기에 코코의 경우 소규모 기업으로 시장 상황에 발 빠르게 대처한다는 게 강점이었는데, 몸집이 커지면 그것이 어렵게 될 것이라는 점도 이유로 들었다.', NULL, NULL, CAST('{"source":"TOPIK35_REPO_PACKAGE","qaStatus":"VISUALLY_VERIFIED"}' AS JSON), NULL, NULL, 40),
    (@rset, @rsec, 'R048_050', 48, 50, '글을 읽고 세 물음에 답하십시오.', 'READING_PASSAGE', 'ko', 'ko', '인터넷 공간에서의 개인 정보 삭제에 관한 법안 제정이 뜨거운 쟁점으로 부각되고 있다. 유럽에서는 이러한 법안이 통과되었고 미국에서도 제한적으로 적용하기로 결정되었다. 우리 사회에서도 그간 피해 사례가 잘 알려져 있기 때문인지 찬성 쪽으로 공감대가 형성되어 있는 듯하다. 그러나 이는 이면에 잠재한 부정적 측면을 고려하지 않은 성급한 동조이다. 이 법안이 실행되었을 때 나타날 수 있는 부작용을 생각해 보라. 삭제된 정보가 흉악범에 관한 것이라면, 특정 기업의 부조리나 공직자의 비리를 고발한 기사라면…… 법 시행의 결과가 개인뿐만 아니라 사회, 국가의 불행으로 이어지지 않는다고 누가 자신할 수 있겠는가? 예컨대 누군가가 후속 범죄의 대상이 될 수도 있고 과거의 행적을 조작한 후보자가 선거에서 당선될 수도 있다. 개인의 권리를 존중하려는 의도가 [BLANK] 장치가 되어서는 안 될 것이다.', NULL, NULL, CAST('{"source":"TOPIK35_REPO_PACKAGE","qaStatus":"VISUALLY_VERIFIED"}' AS JSON), NULL, NULL, 41);
