    (@wset, @wsec, 'Q52', 52, 52, '다음을 읽고 ㉠과 ㉡에 들어갈 말을 각각 한 문장으로 쓰십시오.', 'NONE', 'ko', 'ko', NULL, NULL, NULL, CAST('{"source":"TOPIK35_REPO_PACKAGE","qaStatus":"VISUALLY_VERIFIED"}' AS JSON), NULL, NULL, 1),
    (@wset, @wsec, 'Q53', 53, 53, '다음 그래프를 보고, 연령대에 따라 필요하다고 생각하는 공공시설이 무엇인지 비교하여 그에 대한 자신의 생각을 200~300자로 쓰십시오.', 'NONE', 'ko', 'ko', NULL, NULL, NULL, CAST('{"source":"TOPIK35_REPO_PACKAGE","qaStatus":"VISUALLY_VERIFIED"}' AS JSON), NULL, NULL, 2),
    (@wset, @wsec, 'Q54', 54, 54, '다음을 주제로 하여 자신의 생각을 600~700자로 글을 쓰십시오.', 'NONE', 'ko', 'ko', NULL, NULL, NULL, CAST('{"source":"TOPIK35_REPO_PACKAGE","qaStatus":"VISUALLY_VERIFIED"}' AS JSON), NULL, NULL, 3);
