    (@rset, (SELECT id FROM practice_question_groups WHERE set_id=@rset AND group_label='R003' LIMIT 1), 3, 'SINGLE_CHOICE', '‘눈물이 날 정도로’와 의미가 비슷한 것을 고르십시오.', CAST('["날 만큼","날까 봐","나는 대로","나는 대신에"]' AS JSON), CAST('{"schemaVersion":"question-content-v3","languageTag":"ko","options":[{"id":"opt_1","text":"날 만큼","imageReference":null},{"id":"opt_2","text":"날까 봐","imageReference":null},{"id":"opt_3","text":"나는 대로","imageReference":null},{"id":"opt_4","text":"나는 대신에","imageReference":null}],"blanks":[]}' AS JSON), '1', CAST('{"schemaVersion":"answer-spec-v1","questionType":"SINGLE_CHOICE","correctOptionIds":["opt_1"],"correctValue":null,"blanks":[],"scoringPolicyCode":"ALL_OR_NOTHING"}' AS JSON), NULL, 'rl-explanation-strategy-registry-v2', 'MCQ_OPTION_ELIMINATION', 'v1', 2.00, 2, NULL),
    (@rset, (SELECT id FROM practice_question_groups WHERE set_id=@rset AND group_label='R004' LIMIT 1), 4, 'SINGLE_CHOICE', '‘사이일 뿐이다’와 의미가 비슷한 것을 고르십시오.', CAST('["사이에 불과하다","사이라면 좋겠다","사이일지도 모른다","사이라고 볼 수 없다"]' AS JSON), CAST('{"schemaVersion":"question-content-v3","languageTag":"ko","options":[{"id":"opt_1","text":"사이에 불과하다","imageReference":null},{"id":"opt_2","text":"사이라면 좋겠다","imageReference":null},{"id":"opt_3","text":"사이일지도 모른다","imageReference":null},{"id":"opt_4","text":"사이라고 볼 수 없다","imageReference":null}],"blanks":[]}' AS JSON), '1', CAST('{"schemaVersion":"answer-spec-v1","questionType":"SINGLE_CHOICE","correctOptionIds":["opt_1"],"correctValue":null,"blanks":[],"scoringPolicyCode":"ALL_OR_NOTHING"}' AS JSON), NULL, 'rl-explanation-strategy-registry-v2', 'MCQ_OPTION_ELIMINATION', 'v1', 2.00, 3, NULL),
    (@rset, (SELECT id FROM practice_question_groups WHERE set_id=@rset AND group_label='R005' LIMIT 1), 5, 'SINGLE_CHOICE', '무엇에 대한 글인지 고르십시오.', CAST('["신문","사전","시계","연필"]' AS JSON), CAST('{"schemaVersion":"question-content-v3","languageTag":"ko","options":[{"id":"opt_1","text":"신문","imageReference":null},{"id":"opt_2","text":"사전","imageReference":null},{"id":"opt_3","text":"시계","imageReference":null},{"id":"opt_4","text":"연필","imageReference":null}],"blanks":[]}' AS JSON), '1', CAST('{"schemaVersion":"answer-spec-v1","questionType":"SINGLE_CHOICE","correctOptionIds":["opt_1"],"correctValue":null,"blanks":[],"scoringPolicyCode":"ALL_OR_NOTHING"}' AS JSON), NULL, 'rl-explanation-strategy-registry-v2', 'MCQ_OPTION_ELIMINATION', 'v1', 2.00, 4, NULL),
    (@rset, (SELECT id FROM practice_question_groups WHERE set_id=@rset AND group_label='R006' LIMIT 1), 6, 'SINGLE_CHOICE', '무엇에 대한 글인지 고르십시오.', CAST('["학원","병원","박물관","대사관"]' AS JSON), CAST('{"schemaVersion":"question-content-v3","languageTag":"ko","options":[{"id":"opt_1","text":"학원","imageReference":null},{"id":"opt_2","text":"병원","imageReference":null},{"id":"opt_3","text":"박물관","imageReference":null},{"id":"opt_4","text":"대사관","imageReference":null}],"blanks":[]}' AS JSON), '2', CAST('{"schemaVersion":"answer-spec-v1","questionType":"SINGLE_CHOICE","correctOptionIds":["opt_2"],"correctValue":null,"blanks":[],"scoringPolicyCode":"ALL_OR_NOTHING"}' AS JSON), NULL, 'rl-explanation-strategy-registry-v2', 'MCQ_OPTION_ELIMINATION', 'v1', 2.00, 5, NULL),
    (@rset, (SELECT id FROM practice_question_groups WHERE set_id=@rset AND group_label='R007' LIMIT 1), 7, 'SINGLE_CHOICE', '무엇에 대한 글인지 고르십시오.', CAST('["환경 보호","공원 소개","날씨 정보","여행 계획"]' AS JSON), CAST('{"schemaVersion":"question-content-v3","languageTag":"ko","options":[{"id":"opt_1","text":"환경 보호","imageReference":null},{"id":"opt_2","text":"공원 소개","imageReference":null},{"id":"opt_3","text":"날씨 정보","imageReference":null},{"id":"opt_4","text":"여행 계획","imageReference":null}],"blanks":[]}' AS JSON), '1', CAST('{"schemaVersion":"answer-spec-v1","questionType":"SINGLE_CHOICE","correctOptionIds":["opt_1"],"correctValue":null,"blanks":[],"scoringPolicyCode":"ALL_OR_NOTHING"}' AS JSON), NULL, 'rl-explanation-strategy-registry-v2', 'MCQ_OPTION_ELIMINATION', 'v1', 2.00, 6, NULL),
    (@rset, (SELECT id FROM practice_question_groups WHERE set_id=@rset AND group_label='R008' LIMIT 1), 8, 'SINGLE_CHOICE', '무엇에 대한 글인지 고르십시오.', CAST('["상품 안내","모집 안내","문의 방법","사용 방법"]' AS JSON), CAST('{"schemaVersion":"question-content-v3","languageTag":"ko","options":[{"id":"opt_1","text":"상품 안내","imageReference":null},{"id":"opt_2","text":"모집 안내","imageReference":null},{"id":"opt_3","text":"문의 방법","imageReference":null},{"id":"opt_4","text":"사용 방법","imageReference":null}],"blanks":[]}' AS JSON), '3', CAST('{"schemaVersion":"answer-spec-v1","questionType":"SINGLE_CHOICE","correctOptionIds":["opt_3"],"correctValue":null,"blanks":[],"scoringPolicyCode":"ALL_OR_NOTHING"}' AS JSON), NULL, 'rl-explanation-strategy-registry-v2', 'MCQ_OPTION_ELIMINATION', 'v1', 2.00, 7, NULL),
    (@rset, (SELECT id FROM practice_question_groups WHERE set_id=@rset AND group_label='R009' LIMIT 1), 9, 'SINGLE_CHOICE', '도표의 내용과 같은 것을 고르십시오.', CAST('["주말에는 단체 할인을 받을 수 있다.","이 행사는 이번에 처음 열리는 행사이다.","특별권을 사면 놀이 시설 이용료가 할인된다.","지하철을 타고 가면 입장권을 싸게 살 수 있다."]' AS JSON), CAST('{"schemaVersion":"question-content-v3","languageTag":"ko","options":[{"id":"opt_1","text":"주말에는 단체 할인을 받을 수 있다.","imageReference":null},{"id":"opt_2","text":"이 행사는 이번에 처음 열리는 행사이다.","imageReference":null},{"id":"opt_3","text":"특별권을 사면 놀이 시설 이용료가 할인된다.","imageReference":null},{"id":"opt_4","text":"지하철을 타고 가면 입장권을 싸게 살 수 있다.","imageReference":null}],"blanks":[]}' AS JSON), '4', CAST('{"schemaVersion":"answer-spec-v1","questionType":"SINGLE_CHOICE","correctOptionIds":["opt_4"],"correctValue":null,"blanks":[],"scoringPolicyCode":"ALL_OR_NOTHING"}' AS JSON), NULL, 'rl-explanation-strategy-registry-v2', 'MCQ_OPTION_ELIMINATION', 'v1', 2.00, 8, NULL),
    (@rset, (SELECT id FROM practice_question_groups WHERE set_id=@rset AND group_label='R010' LIMIT 1), 10, 'SINGLE_CHOICE', '도표의 내용과 같은 것을 고르십시오.', CAST('["주인 없는 동물을 데려와 키우는 사람이 가장 적다.","인터넷에서 산 사람이 가게에서 산 사람보다 더 많다.","가게에서 산 사람보다 아는 사람한테서 받은 사람이 더 적다.","아는 사람한테서 동물을 데리고 온 사람은 전체의 반이 넘는다."]' AS JSON), CAST('{"schemaVersion":"question-content-v3","languageTag":"ko","options":[{"id":"opt_1","text":"주인 없는 동물을 데려와 키우는 사람이 가장 적다.","imageReference":null},{"id":"opt_2","text":"인터넷에서 산 사람이 가게에서 산 사람보다 더 많다.","imageReference":null},{"id":"opt_3","text":"가게에서 산 사람보다 아는 사람한테서 받은 사람이 더 적다.","imageReference":null},{"id":"opt_4","text":"아는 사람한테서 동물을 데리고 온 사람은 전체의 반이 넘는다.","imageReference":null}],"blanks":[]}' AS JSON), '1', CAST('{"schemaVersion":"answer-spec-v1","questionType":"SINGLE_CHOICE","correctOptionIds":["opt_1"],"correctValue":null,"blanks":[],"scoringPolicyCode":"ALL_OR_NOTHING"}' AS JSON), NULL, 'rl-explanation-strategy-registry-v2', 'MCQ_OPTION_ELIMINATION', 'v1', 2.00, 9, NULL),
