    (@rset, (SELECT id FROM practice_question_groups WHERE set_id=@rset AND group_label='R025' LIMIT 1), 25, 'SINGLE_CHOICE', '신문 기사 제목을 가장 잘 설명한 것을 고르십시오.', CAST('["허리 건강을 지키려면 가벼운 가방을 메어야 한다.","허리 건강을 위해서는 가방을 메지 않는 것이 좋다.","가방을 계속 같은 방향으로 메면 허리 건강에 좋지 않다.","가방을 오랫동안 메는 것은 허리 건강에 해가 될 수 있다."]' AS JSON), CAST('{"schemaVersion":"question-content-v3","languageTag":"ko","options":[{"id":"opt_1","text":"허리 건강을 지키려면 가벼운 가방을 메어야 한다.","imageReference":null},{"id":"opt_2","text":"허리 건강을 위해서는 가방을 메지 않는 것이 좋다.","imageReference":null},{"id":"opt_3","text":"가방을 계속 같은 방향으로 메면 허리 건강에 좋지 않다.","imageReference":null},{"id":"opt_4","text":"가방을 오랫동안 메는 것은 허리 건강에 해가 될 수 있다.","imageReference":null}],"blanks":[]}' AS JSON), '3', CAST('{"schemaVersion":"answer-spec-v1","questionType":"SINGLE_CHOICE","correctOptionIds":["opt_3"],"correctValue":null,"blanks":[],"scoringPolicyCode":"ALL_OR_NOTHING"}' AS JSON), NULL, 'rl-explanation-strategy-registry-v2', 'MCQ_OPTION_ELIMINATION', 'v1', 2.00, 24, NULL),
    (@rset, (SELECT id FROM practice_question_groups WHERE set_id=@rset AND group_label='R026' LIMIT 1), 26, 'SINGLE_CHOICE', '신문 기사 제목을 가장 잘 설명한 것을 고르십시오.', CAST('["색다른 모양의 간판이 사람들의 눈길을 사로잡고 있다.","간판의 모양을 통일시켜야 사람들이 한눈에 볼 수 있다.","눈에 띄는 간판을 만들기 위해 사람들이 노력하고 있다.","지나치게 큰 간판은 지나다니는 사람들에게 방해가 된다."]' AS JSON), CAST('{"schemaVersion":"question-content-v3","languageTag":"ko","options":[{"id":"opt_1","text":"색다른 모양의 간판이 사람들의 눈길을 사로잡고 있다.","imageReference":null},{"id":"opt_2","text":"간판의 모양을 통일시켜야 사람들이 한눈에 볼 수 있다.","imageReference":null},{"id":"opt_3","text":"눈에 띄는 간판을 만들기 위해 사람들이 노력하고 있다.","imageReference":null},{"id":"opt_4","text":"지나치게 큰 간판은 지나다니는 사람들에게 방해가 된다.","imageReference":null}],"blanks":[]}' AS JSON), '1', CAST('{"schemaVersion":"answer-spec-v1","questionType":"SINGLE_CHOICE","correctOptionIds":["opt_1"],"correctValue":null,"blanks":[],"scoringPolicyCode":"ALL_OR_NOTHING"}' AS JSON), NULL, 'rl-explanation-strategy-registry-v2', 'MCQ_OPTION_ELIMINATION', 'v1', 2.00, 25, NULL),
    (@rset, (SELECT id FROM practice_question_groups WHERE set_id=@rset AND group_label='R027' LIMIT 1), 27, 'SINGLE_CHOICE', '신문 기사 제목을 가장 잘 설명한 것을 고르십시오.', CAST('["정부의 새 대책으로 취업률이 올라가게 될 것이다.","정부의 대책으로 취업률이 더 이상 떨어지지 않았다.","취업률의 변화가 심하여 정부가 대책을 마련하고 있다.","취업률을 높일 수 있는 정부의 실현 가능한 대책이 요구된다."]' AS JSON), CAST('{"schemaVersion":"question-content-v3","languageTag":"ko","options":[{"id":"opt_1","text":"정부의 새 대책으로 취업률이 올라가게 될 것이다.","imageReference":null},{"id":"opt_2","text":"정부의 대책으로 취업률이 더 이상 떨어지지 않았다.","imageReference":null},{"id":"opt_3","text":"취업률의 변화가 심하여 정부가 대책을 마련하고 있다.","imageReference":null},{"id":"opt_4","text":"취업률을 높일 수 있는 정부의 실현 가능한 대책이 요구된다.","imageReference":null}],"blanks":[]}' AS JSON), '4', CAST('{"schemaVersion":"answer-spec-v1","questionType":"SINGLE_CHOICE","correctOptionIds":["opt_4"],"correctValue":null,"blanks":[],"scoringPolicyCode":"ALL_OR_NOTHING"}' AS JSON), NULL, 'rl-explanation-strategy-registry-v2', 'MCQ_OPTION_ELIMINATION', 'v1', 2.00, 26, NULL),
