    (@rset, (SELECT id FROM practice_question_groups WHERE set_id=@rset AND group_label='R032' LIMIT 1), 32, 'SINGLE_CHOICE', '글의 내용과 같은 것을 고르십시오.', CAST('["기내가 건조해서 사람들의 입맛이 예민해진다.","기내식은 좀 더 짜게 만들어야 맛을 낼 수 있다.","음식 온도를 유지하기 위해 기내식을 포장해 놓는다.","음식에 있는 수분을 줄여 기내식이 상하는 것을 방지한다."]' AS JSON), CAST('{"schemaVersion":"question-content-v3","languageTag":"ko","options":[{"id":"opt_1","text":"기내가 건조해서 사람들의 입맛이 예민해진다.","imageReference":null},{"id":"opt_2","text":"기내식은 좀 더 짜게 만들어야 맛을 낼 수 있다.","imageReference":null},{"id":"opt_3","text":"음식 온도를 유지하기 위해 기내식을 포장해 놓는다.","imageReference":null},{"id":"opt_4","text":"음식에 있는 수분을 줄여 기내식이 상하는 것을 방지한다.","imageReference":null}],"blanks":[]}' AS JSON), '2', CAST('{"schemaVersion":"answer-spec-v1","questionType":"SINGLE_CHOICE","correctOptionIds":["opt_2"],"correctValue":null,"blanks":[],"scoringPolicyCode":"ALL_OR_NOTHING"}' AS JSON), NULL, 'rl-explanation-strategy-registry-v2', 'MCQ_OPTION_ELIMINATION', 'v1', 2.00, 31, NULL),
    (@rset, (SELECT id FROM practice_question_groups WHERE set_id=@rset AND group_label='R033' LIMIT 1), 33, 'SINGLE_CHOICE', '글의 내용과 같은 것을 고르십시오.', CAST('["예전에 비해 도시에 사는 벌의 수가 줄었다.","벌을 쫓기 위해 도시의 식물에 약을 뿌리고 있다.","도시의 벌 피해 방지법에 대한 연구가 진행 중이다.","도시의 공원이 벌이 살 수 있는 좋은 환경을 제공한다."]' AS JSON), CAST('{"schemaVersion":"question-content-v3","languageTag":"ko","options":[{"id":"opt_1","text":"예전에 비해 도시에 사는 벌의 수가 줄었다.","imageReference":null},{"id":"opt_2","text":"벌을 쫓기 위해 도시의 식물에 약을 뿌리고 있다.","imageReference":null},{"id":"opt_3","text":"도시의 벌 피해 방지법에 대한 연구가 진행 중이다.","imageReference":null},{"id":"opt_4","text":"도시의 공원이 벌이 살 수 있는 좋은 환경을 제공한다.","imageReference":null}],"blanks":[]}' AS JSON), '4', CAST('{"schemaVersion":"answer-spec-v1","questionType":"SINGLE_CHOICE","correctOptionIds":["opt_4"],"correctValue":null,"blanks":[],"scoringPolicyCode":"ALL_OR_NOTHING"}' AS JSON), NULL, 'rl-explanation-strategy-registry-v2', 'MCQ_OPTION_ELIMINATION', 'v1', 2.00, 32, NULL),
    (@rset, (SELECT id FROM practice_question_groups WHERE set_id=@rset AND group_label='R034' LIMIT 1), 34, 'SINGLE_CHOICE', '글의 내용과 같은 것을 고르십시오.', CAST('["휴가 기간이 늘어나면 경제에 악영향을 끼친다.","국내 관광업과 관련된 일자리는 5만 개 정도이다.","관광업계에서 이 캠페인을 기획하여 진행하고 있다.","이 캠페인은 국내 관광을 활성화하기 위해 시작되었다."]' AS JSON), CAST('{"schemaVersion":"question-content-v3","languageTag":"ko","options":[{"id":"opt_1","text":"휴가 기간이 늘어나면 경제에 악영향을 끼친다.","imageReference":null},{"id":"opt_2","text":"국내 관광업과 관련된 일자리는 5만 개 정도이다.","imageReference":null},{"id":"opt_3","text":"관광업계에서 이 캠페인을 기획하여 진행하고 있다.","imageReference":null},{"id":"opt_4","text":"이 캠페인은 국내 관광을 활성화하기 위해 시작되었다.","imageReference":null}],"blanks":[]}' AS JSON), '4', CAST('{"schemaVersion":"answer-spec-v1","questionType":"SINGLE_CHOICE","correctOptionIds":["opt_4"],"correctValue":null,"blanks":[],"scoringPolicyCode":"ALL_OR_NOTHING"}' AS JSON), NULL, 'rl-explanation-strategy-registry-v2', 'MCQ_OPTION_ELIMINATION', 'v1', 2.00, 33, NULL),
    (@rset, (SELECT id FROM practice_question_groups WHERE set_id=@rset AND group_label='R035' LIMIT 1), 35, 'SINGLE_CHOICE', '글의 주제로 가장 알맞은 것을 고르십시오.', CAST('["미혼이라는 말은 결혼에 대한 다양한 의미를 포괄한다.","비혼이라는 말은 결혼에 대한 인식의 변화를 보여 준다.","비혼과 미혼은 같은 대상을 가리키므로 의미의 차이는 없다.","미혼이라는 말은 결혼을 계획하는 사람들에게 부적절한 표현이다."]' AS JSON), CAST('{"schemaVersion":"question-content-v3","languageTag":"ko","options":[{"id":"opt_1","text":"미혼이라는 말은 결혼에 대한 다양한 의미를 포괄한다.","imageReference":null},{"id":"opt_2","text":"비혼이라는 말은 결혼에 대한 인식의 변화를 보여 준다.","imageReference":null},{"id":"opt_3","text":"비혼과 미혼은 같은 대상을 가리키므로 의미의 차이는 없다.","imageReference":null},{"id":"opt_4","text":"미혼이라는 말은 결혼을 계획하는 사람들에게 부적절한 표현이다.","imageReference":null}],"blanks":[]}' AS JSON), '2', CAST('{"schemaVersion":"answer-spec-v1","questionType":"SINGLE_CHOICE","correctOptionIds":["opt_2"],"correctValue":null,"blanks":[],"scoringPolicyCode":"ALL_OR_NOTHING"}' AS JSON), NULL, 'rl-explanation-strategy-registry-v2', 'MCQ_OPTION_ELIMINATION', 'v1', 2.00, 34, NULL),
    (@rset, (SELECT id FROM practice_question_groups WHERE set_id=@rset AND group_label='R036' LIMIT 1), 36, 'SINGLE_CHOICE', '글의 주제로 가장 알맞은 것을 고르십시오.', CAST('["회사의 이미지를 비즈니스 패션을 통해 연출하라.","비즈니스 상황에 부합하는 패션 전략을 활용하라.","회사를 상징하는 색상으로 편안한 분위기를 조성하라.","부드러운 이미지 연출을 위한 비즈니스 전략을 세워라."]' AS JSON), CAST('{"schemaVersion":"question-content-v3","languageTag":"ko","options":[{"id":"opt_1","text":"회사의 이미지를 비즈니스 패션을 통해 연출하라.","imageReference":null},{"id":"opt_2","text":"비즈니스 상황에 부합하는 패션 전략을 활용하라.","imageReference":null},{"id":"opt_3","text":"회사를 상징하는 색상으로 편안한 분위기를 조성하라.","imageReference":null},{"id":"opt_4","text":"부드러운 이미지 연출을 위한 비즈니스 전략을 세워라.","imageReference":null}],"blanks":[]}' AS JSON), '2', CAST('{"schemaVersion":"answer-spec-v1","questionType":"SINGLE_CHOICE","correctOptionIds":["opt_2"],"correctValue":null,"blanks":[],"scoringPolicyCode":"ALL_OR_NOTHING"}' AS JSON), NULL, 'rl-explanation-strategy-registry-v2', 'MCQ_OPTION_ELIMINATION', 'v1', 2.00, 35, NULL),
    (@rset, (SELECT id FROM practice_question_groups WHERE set_id=@rset AND group_label='R037' LIMIT 1), 37, 'SINGLE_CHOICE', '글의 주제로 가장 알맞은 것을 고르십시오.', CAST('["소진증후군이 사회에 미치는 영향을 분석해야 한다.","소진증후군의 원인과 증상의 관계를 파악해야 한다.","소진증후군의 증상에 맞는 치료법을 개발해야 한다.","소진증후군이 발생하지 않도록 사전에 노력해야 한다."]' AS JSON), CAST('{"schemaVersion":"question-content-v3","languageTag":"ko","options":[{"id":"opt_1","text":"소진증후군이 사회에 미치는 영향을 분석해야 한다.","imageReference":null},{"id":"opt_2","text":"소진증후군의 원인과 증상의 관계를 파악해야 한다.","imageReference":null},{"id":"opt_3","text":"소진증후군의 증상에 맞는 치료법을 개발해야 한다.","imageReference":null},{"id":"opt_4","text":"소진증후군이 발생하지 않도록 사전에 노력해야 한다.","imageReference":null}],"blanks":[]}' AS JSON), '4', CAST('{"schemaVersion":"answer-spec-v1","questionType":"SINGLE_CHOICE","correctOptionIds":["opt_4"],"correctValue":null,"blanks":[],"scoringPolicyCode":"ALL_OR_NOTHING"}' AS JSON), NULL, 'rl-explanation-strategy-registry-v2', 'MCQ_OPTION_ELIMINATION', 'v1', 2.00, 36, NULL),
    (@rset, (SELECT id FROM practice_question_groups WHERE set_id=@rset AND group_label='R038' LIMIT 1), 38, 'SINGLE_CHOICE', '글의 주제로 가장 알맞은 것을 고르십시오.', CAST('["로봇의 등장으로 인간의 지식 노동 시간이 감소하게 될 것이다.","로봇의 등장으로 인간은 육체노동의 시간을 줄일 수 있을 것이다.","로봇의 등장으로 인간의 노동력 시장 규모가 점점 축소될 것이다.","로봇의 등장으로 인간은 질적인 업무에 집중할 수 있게 될 것이다."]' AS JSON), CAST('{"schemaVersion":"question-content-v3","languageTag":"ko","options":[{"id":"opt_1","text":"로봇의 등장으로 인간의 지식 노동 시간이 감소하게 될 것이다.","imageReference":null},{"id":"opt_2","text":"로봇의 등장으로 인간은 육체노동의 시간을 줄일 수 있을 것이다.","imageReference":null},{"id":"opt_3","text":"로봇의 등장으로 인간의 노동력 시장 규모가 점점 축소될 것이다.","imageReference":null},{"id":"opt_4","text":"로봇의 등장으로 인간은 질적인 업무에 집중할 수 있게 될 것이다.","imageReference":null}],"blanks":[]}' AS JSON), '4', CAST('{"schemaVersion":"answer-spec-v1","questionType":"SINGLE_CHOICE","correctOptionIds":["opt_4"],"correctValue":null,"blanks":[],"scoringPolicyCode":"ALL_OR_NOTHING"}' AS JSON), NULL, 'rl-explanation-strategy-registry-v2', 'MCQ_OPTION_ELIMINATION', 'v1', 2.00, 37, NULL),
