    (@rset, (SELECT id FROM practice_question_groups WHERE set_id=@rset AND group_label='R042_043' LIMIT 1), 43, 'SINGLE_CHOICE', '글의 내용과 같은 것을 고르십시오.', CAST('["아이가 올라간 다이빙대는 어린이 전용으로 만들어졌다.","아이가 뛰어내려 물속으로 들어가자 사람들이 박수를 쳤다.","방송을 통해 아이의 부모가 아이에게 내려오라고 소리쳤다.","아이의 부모는 관리자에게 아이를 데려와 달라고 부탁했다."]' AS JSON), CAST('{"schemaVersion":"question-content-v3","languageTag":"ko","options":[{"id":"opt_1","text":"아이가 올라간 다이빙대는 어린이 전용으로 만들어졌다.","imageReference":null},{"id":"opt_2","text":"아이가 뛰어내려 물속으로 들어가자 사람들이 박수를 쳤다.","imageReference":null},{"id":"opt_3","text":"방송을 통해 아이의 부모가 아이에게 내려오라고 소리쳤다.","imageReference":null},{"id":"opt_4","text":"아이의 부모는 관리자에게 아이를 데려와 달라고 부탁했다.","imageReference":null}],"blanks":[]}' AS JSON), '2', CAST('{"schemaVersion":"answer-spec-v1","questionType":"SINGLE_CHOICE","correctOptionIds":["opt_2"],"correctValue":null,"blanks":[],"scoringPolicyCode":"ALL_OR_NOTHING"}' AS JSON), NULL, 'rl-explanation-strategy-registry-v2', 'MCQ_OPTION_ELIMINATION', 'v1', 2.00, 42, NULL),
    (@rset, (SELECT id FROM practice_question_groups WHERE set_id=@rset AND group_label='R044_045' LIMIT 1), 44, 'SINGLE_CHOICE', '글의 주제로 알맞은 것을 고르십시오.', CAST('["기업이 동의하지 않는 제도의 시행은 지양해야 한다.","배출권 할당은 기업의 사정에 따라 조정되어야 한다.","배출권 할당은 의도적인 거래를 염두에 두어야 한다.","현실성을 고려한 환경 보호 대책이 마련되어야 한다."]' AS JSON), CAST('{"schemaVersion":"question-content-v3","languageTag":"ko","options":[{"id":"opt_1","text":"기업이 동의하지 않는 제도의 시행은 지양해야 한다.","imageReference":null},{"id":"opt_2","text":"배출권 할당은 기업의 사정에 따라 조정되어야 한다.","imageReference":null},{"id":"opt_3","text":"배출권 할당은 의도적인 거래를 염두에 두어야 한다.","imageReference":null},{"id":"opt_4","text":"현실성을 고려한 환경 보호 대책이 마련되어야 한다.","imageReference":null}],"blanks":[]}' AS JSON), '2', CAST('{"schemaVersion":"answer-spec-v1","questionType":"SINGLE_CHOICE","correctOptionIds":["opt_2"],"correctValue":null,"blanks":[],"scoringPolicyCode":"ALL_OR_NOTHING"}' AS JSON), NULL, 'rl-explanation-strategy-registry-v2', 'MCQ_OPTION_ELIMINATION', 'v1', 2.00, 43, NULL),
    (@rset, (SELECT id FROM practice_question_groups WHERE set_id=@rset AND group_label='R044_045' LIMIT 1), 45, 'SINGLE_CHOICE', '빈칸에 들어갈 내용으로 알맞은 것을 고르십시오.', CAST('["배출량이 할당된 양에 못 미친","온실가스 총량을 신고하지 않은","매출이 늘어 공장 가동률이 높아진","경영진의 배출량 감소 의지가 강한"]' AS JSON), CAST('{"schemaVersion":"question-content-v3","languageTag":"ko","options":[{"id":"opt_1","text":"배출량이 할당된 양에 못 미친","imageReference":null},{"id":"opt_2","text":"온실가스 총량을 신고하지 않은","imageReference":null},{"id":"opt_3","text":"매출이 늘어 공장 가동률이 높아진","imageReference":null},{"id":"opt_4","text":"경영진의 배출량 감소 의지가 강한","imageReference":null}],"blanks":[]}' AS JSON), '3', CAST('{"schemaVersion":"answer-spec-v1","questionType":"SINGLE_CHOICE","correctOptionIds":["opt_3"],"correctValue":null,"blanks":[],"scoringPolicyCode":"ALL_OR_NOTHING"}' AS JSON), NULL, 'rl-explanation-strategy-registry-v2', 'MCQ_OPTION_ELIMINATION', 'v1', 2.00, 44, NULL),
