    (@rset, (SELECT id FROM practice_question_groups WHERE set_id=@rset AND group_label='R046_047' LIMIT 1), 47, 'SINGLE_CHOICE', '글의 내용과 같은 것을 고르십시오.', CAST('["양 기업의 합병은 코코의 경영 부진에 의한 것이다.","양 기업의 규모는 동종 업계에서 우열을 가리기 어렵다.","코코는 그동안 신속한 업무 처리로 재계의 인정을 받아 왔다.","둠과 코코의 합병에 대한 예측들은 긍정적이라는 공통점이 있다."]' AS JSON), CAST('{"schemaVersion":"question-content-v3","languageTag":"ko","options":[{"id":"opt_1","text":"양 기업의 합병은 코코의 경영 부진에 의한 것이다.","imageReference":null},{"id":"opt_2","text":"양 기업의 규모는 동종 업계에서 우열을 가리기 어렵다.","imageReference":null},{"id":"opt_3","text":"코코는 그동안 신속한 업무 처리로 재계의 인정을 받아 왔다.","imageReference":null},{"id":"opt_4","text":"둠과 코코의 합병에 대한 예측들은 긍정적이라는 공통점이 있다.","imageReference":null}],"blanks":[]}' AS JSON), '3', CAST('{"schemaVersion":"answer-spec-v1","questionType":"SINGLE_CHOICE","correctOptionIds":["opt_3"],"correctValue":null,"blanks":[],"scoringPolicyCode":"ALL_OR_NOTHING"}' AS JSON), NULL, 'rl-explanation-strategy-registry-v2', 'MCQ_OPTION_ELIMINATION', 'v1', 2.00, 46, NULL),
    (@rset, (SELECT id FROM practice_question_groups WHERE set_id=@rset AND group_label='R048_050' LIMIT 1), 48, 'SINGLE_CHOICE', '필자가 이 글을 쓴 목적을 고르십시오.', CAST('["법 제정의 공론화를 촉구하기 위해","법 제정의 반대 근거를 제시하기 위해","법 시행의 피해 사례를 알려 주기 위해","법 시행의 적절한 시기를 제안하기 위해"]' AS JSON), CAST('{"schemaVersion":"question-content-v3","languageTag":"ko","options":[{"id":"opt_1","text":"법 제정의 공론화를 촉구하기 위해","imageReference":null},{"id":"opt_2","text":"법 제정의 반대 근거를 제시하기 위해","imageReference":null},{"id":"opt_3","text":"법 시행의 피해 사례를 알려 주기 위해","imageReference":null},{"id":"opt_4","text":"법 시행의 적절한 시기를 제안하기 위해","imageReference":null}],"blanks":[]}' AS JSON), '2', CAST('{"schemaVersion":"answer-spec-v1","questionType":"SINGLE_CHOICE","correctOptionIds":["opt_2"],"correctValue":null,"blanks":[],"scoringPolicyCode":"ALL_OR_NOTHING"}' AS JSON), NULL, 'rl-explanation-strategy-registry-v2', 'MCQ_OPTION_ELIMINATION', 'v1', 2.00, 47, NULL),
    (@rset, (SELECT id FROM practice_question_groups WHERE set_id=@rset AND group_label='R048_050' LIMIT 1), 49, 'SINGLE_CHOICE', '빈칸에 들어갈 내용으로 알맞은 것을 고르십시오.', CAST('["공공의 피해를 유발하는","국민의 자유를 침해하는","소통의 단절을 조장하는","사회의 통합을 저해하는"]' AS JSON), CAST('{"schemaVersion":"question-content-v3","languageTag":"ko","options":[{"id":"opt_1","text":"공공의 피해를 유발하는","imageReference":null},{"id":"opt_2","text":"국민의 자유를 침해하는","imageReference":null},{"id":"opt_3","text":"소통의 단절을 조장하는","imageReference":null},{"id":"opt_4","text":"사회의 통합을 저해하는","imageReference":null}],"blanks":[]}' AS JSON), '1', CAST('{"schemaVersion":"answer-spec-v1","questionType":"SINGLE_CHOICE","correctOptionIds":["opt_1"],"correctValue":null,"blanks":[],"scoringPolicyCode":"ALL_OR_NOTHING"}' AS JSON), NULL, 'rl-explanation-strategy-registry-v2', 'MCQ_OPTION_ELIMINATION', 'v1', 2.00, 48, NULL),
    (@rset, (SELECT id FROM practice_question_groups WHERE set_id=@rset AND group_label='R048_050' LIMIT 1), 50, 'SINGLE_CHOICE', '‘법 시행의 결과가 개인뿐만 아니라 사회, 국가의 불행으로 이어지지 않는다고 누가 자신할 수 있겠는가?’에 나타난 필자의 태도로 알맞은 것을 고르십시오.', CAST('["이 법으로 피해를 입은 사람들을 동정하고 있다.","이 법의 제정 단계에서의 문제점을 지적하고 있다.","이 법이 실패했던 해외 사례에 대해 비판하고 있다.","이 법의 시행이 가져올 부작용에 대해 염려하고 있다."]' AS JSON), CAST('{"schemaVersion":"question-content-v3","languageTag":"ko","options":[{"id":"opt_1","text":"이 법으로 피해를 입은 사람들을 동정하고 있다.","imageReference":null},{"id":"opt_2","text":"이 법의 제정 단계에서의 문제점을 지적하고 있다.","imageReference":null},{"id":"opt_3","text":"이 법이 실패했던 해외 사례에 대해 비판하고 있다.","imageReference":null},{"id":"opt_4","text":"이 법의 시행이 가져올 부작용에 대해 염려하고 있다.","imageReference":null}],"blanks":[]}' AS JSON), '4', CAST('{"schemaVersion":"answer-spec-v1","questionType":"SINGLE_CHOICE","correctOptionIds":["opt_4"],"correctValue":null,"blanks":[],"scoringPolicyCode":"ALL_OR_NOTHING"}' AS JSON), NULL, 'rl-explanation-strategy-registry-v2', 'MCQ_OPTION_ELIMINATION', 'v1', 2.00, 49, NULL);
