    (@lset, (SELECT id FROM practice_question_groups WHERE set_id=@lset AND group_label='L01_03' LIMIT 1), 3, 'SINGLE_CHOICE', '다음을 듣고 알맞은 그림을 고르십시오.', CAST('["①","②","③","④"]' AS JSON), CAST('{"schemaVersion":"question-content-v3","languageTag":"ko","options":[{"id":"opt_1","text":"①","imageReference":"/images/practice/topik35/a4a0ddcfb7df8903a9d808015ac4ba1d7960cefe8a7090a65e7f696f3189c701.png"},{"id":"opt_2","text":"②","imageReference":"/images/practice/topik35/3a8d0ef873b70173b794cad53358dfb61fb427e4c6a052c7fe0c6ba206f9efb1.png"},{"id":"opt_3","text":"③","imageReference":"/images/practice/topik35/f373b68cfb3ea7e86dc54914d448746f70e5ee5cdfe70c0ca6989eb3ae19c0d3.png"},{"id":"opt_4","text":"④","imageReference":"/images/practice/topik35/1f12a8f60e3575263d7a28b80ed51fac1eb6b5c37d25ea35f2e8559bf7a817e5.png"}],"blanks":[]}' AS JSON), '1', CAST('{"schemaVersion":"answer-spec-v1","questionType":"SINGLE_CHOICE","correctOptionIds":["opt_1"],"correctValue":null,"blanks":[],"scoringPolicyCode":"ALL_OR_NOTHING"}' AS JSON), NULL, 'rl-explanation-strategy-registry-v2', 'MCQ_OPTION_ELIMINATION', 'v1', 2.00, 2, NULL),
    (@lset, (SELECT id FROM practice_question_groups WHERE set_id=@lset AND group_label='L04_08' LIMIT 1), 4, 'SINGLE_CHOICE', '다음 대화를 잘 듣고 이어질 수 있는 말을 고르십시오.', CAST('["기다리게 해서 죄송합니다.","내일은 꼭 나가도록 하겠습니다.","감기에 잘 걸리지 않는 편입니다.","오늘 못 가게 되면 전화 드리겠습니다."]' AS JSON), CAST('{"schemaVersion":"question-content-v3","languageTag":"ko","options":[{"id":"opt_1","text":"기다리게 해서 죄송합니다.","imageReference":null},{"id":"opt_2","text":"내일은 꼭 나가도록 하겠습니다.","imageReference":null},{"id":"opt_3","text":"감기에 잘 걸리지 않는 편입니다.","imageReference":null},{"id":"opt_4","text":"오늘 못 가게 되면 전화 드리겠습니다.","imageReference":null}],"blanks":[]}' AS JSON), '2', CAST('{"schemaVersion":"answer-spec-v1","questionType":"SINGLE_CHOICE","correctOptionIds":["opt_2"],"correctValue":null,"blanks":[],"scoringPolicyCode":"ALL_OR_NOTHING"}' AS JSON), NULL, 'rl-explanation-strategy-registry-v2', 'MCQ_OPTION_ELIMINATION', 'v1', 2.00, 3, NULL),
    (@lset, (SELECT id FROM practice_question_groups WHERE set_id=@lset AND group_label='L04_08' LIMIT 1), 5, 'SINGLE_CHOICE', '다음 대화를 잘 듣고 이어질 수 있는 말을 고르십시오.', CAST('["제시간에 도착해서 다행이에요.","기차가 예정보다 늦게 오겠는데요.","일을 하느라 기차를 놓칠 뻔했어요.","비가 와서 그 시간까지는 힘들겠는데요."]' AS JSON), CAST('{"schemaVersion":"question-content-v3","languageTag":"ko","options":[{"id":"opt_1","text":"제시간에 도착해서 다행이에요.","imageReference":null},{"id":"opt_2","text":"기차가 예정보다 늦게 오겠는데요.","imageReference":null},{"id":"opt_3","text":"일을 하느라 기차를 놓칠 뻔했어요.","imageReference":null},{"id":"opt_4","text":"비가 와서 그 시간까지는 힘들겠는데요.","imageReference":null}],"blanks":[]}' AS JSON), '4', CAST('{"schemaVersion":"answer-spec-v1","questionType":"SINGLE_CHOICE","correctOptionIds":["opt_4"],"correctValue":null,"blanks":[],"scoringPolicyCode":"ALL_OR_NOTHING"}' AS JSON), NULL, 'rl-explanation-strategy-registry-v2', 'MCQ_OPTION_ELIMINATION', 'v1', 2.00, 4, NULL),
    (@lset, (SELECT id FROM practice_question_groups WHERE set_id=@lset AND group_label='L04_08' LIMIT 1), 6, 'SINGLE_CHOICE', '다음 대화를 잘 듣고 이어질 수 있는 말을 고르십시오.', CAST('["안 그래도 다 팔렸더라고요.","어제 벌써 하나 사 왔어요.","저도 한번 만들어 보려고요.","저도 가게에 가서 사야겠어요."]' AS JSON), CAST('{"schemaVersion":"question-content-v3","languageTag":"ko","options":[{"id":"opt_1","text":"안 그래도 다 팔렸더라고요.","imageReference":null},{"id":"opt_2","text":"어제 벌써 하나 사 왔어요.","imageReference":null},{"id":"opt_3","text":"저도 한번 만들어 보려고요.","imageReference":null},{"id":"opt_4","text":"저도 가게에 가서 사야겠어요.","imageReference":null}],"blanks":[]}' AS JSON), '3', CAST('{"schemaVersion":"answer-spec-v1","questionType":"SINGLE_CHOICE","correctOptionIds":["opt_3"],"correctValue":null,"blanks":[],"scoringPolicyCode":"ALL_OR_NOTHING"}' AS JSON), NULL, 'rl-explanation-strategy-registry-v2', 'MCQ_OPTION_ELIMINATION', 'v1', 2.00, 5, NULL),
    (@lset, (SELECT id FROM practice_question_groups WHERE set_id=@lset AND group_label='L04_08' LIMIT 1), 7, 'SINGLE_CHOICE', '다음 대화를 잘 듣고 이어질 수 있는 말을 고르십시오.', CAST('["거실이 좀 넓으면 좋겠어.","그럼 저쪽으로 옮겨야겠네.","이따가 몇 개 더 갖다 놓을게.","화분이 없어서 허전한 것 같아."]' AS JSON), CAST('{"schemaVersion":"question-content-v3","languageTag":"ko","options":[{"id":"opt_1","text":"거실이 좀 넓으면 좋겠어.","imageReference":null},{"id":"opt_2","text":"그럼 저쪽으로 옮겨야겠네.","imageReference":null},{"id":"opt_3","text":"이따가 몇 개 더 갖다 놓을게.","imageReference":null},{"id":"opt_4","text":"화분이 없어서 허전한 것 같아.","imageReference":null}],"blanks":[]}' AS JSON), '2', CAST('{"schemaVersion":"answer-spec-v1","questionType":"SINGLE_CHOICE","correctOptionIds":["opt_2"],"correctValue":null,"blanks":[],"scoringPolicyCode":"ALL_OR_NOTHING"}' AS JSON), NULL, 'rl-explanation-strategy-registry-v2', 'MCQ_OPTION_ELIMINATION', 'v1', 2.00, 6, NULL),
    (@lset, (SELECT id FROM practice_question_groups WHERE set_id=@lset AND group_label='L04_08' LIMIT 1), 8, 'SINGLE_CHOICE', '다음 대화를 잘 듣고 이어질 수 있는 말을 고르십시오.', CAST('["신청서만 쓰면 빌릴 수 있어서 참 편해요.","빌려가는 사람들이 생각보다 적었나 봐요.","우산은 내일 출근하는 길에 갖다 드릴게요.","필요할 때 빌릴 수 있어서 좋았는데 아쉽네요."]' AS JSON), CAST('{"schemaVersion":"question-content-v3","languageTag":"ko","options":[{"id":"opt_1","text":"신청서만 쓰면 빌릴 수 있어서 참 편해요.","imageReference":null},{"id":"opt_2","text":"빌려가는 사람들이 생각보다 적었나 봐요.","imageReference":null},{"id":"opt_3","text":"우산은 내일 출근하는 길에 갖다 드릴게요.","imageReference":null},{"id":"opt_4","text":"필요할 때 빌릴 수 있어서 좋았는데 아쉽네요.","imageReference":null}],"blanks":[]}' AS JSON), '4', CAST('{"schemaVersion":"answer-spec-v1","questionType":"SINGLE_CHOICE","correctOptionIds":["opt_4"],"correctValue":null,"blanks":[],"scoringPolicyCode":"ALL_OR_NOTHING"}' AS JSON), NULL, 'rl-explanation-strategy-registry-v2', 'MCQ_OPTION_ELIMINATION', 'v1', 2.00, 7, NULL),
    (@lset, (SELECT id FROM practice_question_groups WHERE set_id=@lset AND group_label='L09_12' LIMIT 1), 9, 'SINGLE_CHOICE', '다음 대화를 잘 듣고 여자가 이어서 할 행동으로 알맞은 것을 고르십시오.', CAST('["침대의 사진을 찍는다.","가게로 침대를 가져간다.","침대를 만든 회사에 연락한다.","중고 가게에 가서 침대를 산다."]' AS JSON), CAST('{"schemaVersion":"question-content-v3","languageTag":"ko","options":[{"id":"opt_1","text":"침대의 사진을 찍는다.","imageReference":null},{"id":"opt_2","text":"가게로 침대를 가져간다.","imageReference":null},{"id":"opt_3","text":"침대를 만든 회사에 연락한다.","imageReference":null},{"id":"opt_4","text":"중고 가게에 가서 침대를 산다.","imageReference":null}],"blanks":[]}' AS JSON), '1', CAST('{"schemaVersion":"answer-spec-v1","questionType":"SINGLE_CHOICE","correctOptionIds":["opt_1"],"correctValue":null,"blanks":[],"scoringPolicyCode":"ALL_OR_NOTHING"}' AS JSON), NULL, 'rl-explanation-strategy-registry-v2', 'MCQ_OPTION_ELIMINATION', 'v1', 2.00, 8, NULL),
    (@lset, (SELECT id FROM practice_question_groups WHERE set_id=@lset AND group_label='L09_12' LIMIT 1), 10, 'SINGLE_CHOICE', '다음 대화를 잘 듣고 여자가 이어서 할 행동으로 알맞은 것을 고르십시오.', CAST('["복사기를 수리할 사람을 찾는다.","복사기의 종류와 가격을 조사한다.","구매팀에 복사기 상태를 설명한다.","사무실에서 쓸 복사기를 사러 간다."]' AS JSON), CAST('{"schemaVersion":"question-content-v3","languageTag":"ko","options":[{"id":"opt_1","text":"복사기를 수리할 사람을 찾는다.","imageReference":null},{"id":"opt_2","text":"복사기의 종류와 가격을 조사한다.","imageReference":null},{"id":"opt_3","text":"구매팀에 복사기 상태를 설명한다.","imageReference":null},{"id":"opt_4","text":"사무실에서 쓸 복사기를 사러 간다.","imageReference":null}],"blanks":[]}' AS JSON), '3', CAST('{"schemaVersion":"answer-spec-v1","questionType":"SINGLE_CHOICE","correctOptionIds":["opt_3"],"correctValue":null,"blanks":[],"scoringPolicyCode":"ALL_OR_NOTHING"}' AS JSON), NULL, 'rl-explanation-strategy-registry-v2', 'MCQ_OPTION_ELIMINATION', 'v1', 2.00, 9, NULL),
