    (@lset, (SELECT id FROM practice_question_groups WHERE set_id=@lset AND group_label='L17_20' LIMIT 1), 20, 'SINGLE_CHOICE', '다음을 듣고 남자의 중심 생각을 고르십시오.', CAST('["전통 한복의 특징을 지키는 것이 중요하다.","화려한 디자인의 한복은 대중화가 어렵다.","전통 한복의 색과 선은 표현하기가 까다롭다.","한복의 대중화를 위해 색과 디자인을 바꿔야 한다."]' AS JSON), CAST('{"schemaVersion":"question-content-v3","languageTag":"ko","options":[{"id":"opt_1","text":"전통 한복의 특징을 지키는 것이 중요하다.","imageReference":null},{"id":"opt_2","text":"화려한 디자인의 한복은 대중화가 어렵다.","imageReference":null},{"id":"opt_3","text":"전통 한복의 색과 선은 표현하기가 까다롭다.","imageReference":null},{"id":"opt_4","text":"한복의 대중화를 위해 색과 디자인을 바꿔야 한다.","imageReference":null}],"blanks":[]}' AS JSON), '1', CAST('{"schemaVersion":"answer-spec-v1","questionType":"SINGLE_CHOICE","correctOptionIds":["opt_1"],"correctValue":null,"blanks":[],"scoringPolicyCode":"ALL_OR_NOTHING"}' AS JSON), NULL, 'rl-explanation-strategy-registry-v2', 'MCQ_OPTION_ELIMINATION', 'v1', 2.00, 19, NULL),
