    (@lset, (SELECT id FROM practice_question_groups WHERE set_id=@lset AND group_label='L37_38' LIMIT 1), 37, 'SINGLE_CHOICE', '남자의 중심 생각으로 맞는 것을 고르십시오.', CAST('["어떤 분야든지 만 시간을 투자하면 전문성이 쌓인다.","전문가가 되려면 한계를 극복하려는 노력이 필요하다.","자신에게 익숙하고 편안한 것에서 벗어나는 것이 좋다.","무조건 만 시간을 채운다고 해서 성공하는 것은 아니다."]' AS JSON), CAST('{"schemaVersion":"question-content-v3","languageTag":"ko","options":[{"id":"opt_1","text":"어떤 분야든지 만 시간을 투자하면 전문성이 쌓인다.","imageReference":null},{"id":"opt_2","text":"전문가가 되려면 한계를 극복하려는 노력이 필요하다.","imageReference":null},{"id":"opt_3","text":"자신에게 익숙하고 편안한 것에서 벗어나는 것이 좋다.","imageReference":null},{"id":"opt_4","text":"무조건 만 시간을 채운다고 해서 성공하는 것은 아니다.","imageReference":null}],"blanks":[]}' AS JSON), '2', CAST('{"schemaVersion":"answer-spec-v1","questionType":"SINGLE_CHOICE","correctOptionIds":["opt_2"],"correctValue":null,"blanks":[],"scoringPolicyCode":"ALL_OR_NOTHING"}' AS JSON), NULL, 'rl-explanation-strategy-registry-v2', 'MCQ_OPTION_ELIMINATION', 'v1', 2.00, 36, NULL),
    (@lset, (SELECT id FROM practice_question_groups WHERE set_id=@lset AND group_label='L37_38' LIMIT 1), 38, 'SINGLE_CHOICE', '들은 내용과 일치하는 것을 고르십시오.', CAST('["10년 이내에 만 시간을 채워야 전문가가 될 수 있다.","음악 분야에서는 1만 시간의 법칙이 적용되지 않는다.","익숙한 곡을 오랜 기간 연습하면 전문가가 될 수 있다.","성공할 수 있는 기본 조건은 만 시간을 투자하는 것이다."]' AS JSON), CAST('{"schemaVersion":"question-content-v3","languageTag":"ko","options":[{"id":"opt_1","text":"10년 이내에 만 시간을 채워야 전문가가 될 수 있다.","imageReference":null},{"id":"opt_2","text":"음악 분야에서는 1만 시간의 법칙이 적용되지 않는다.","imageReference":null},{"id":"opt_3","text":"익숙한 곡을 오랜 기간 연습하면 전문가가 될 수 있다.","imageReference":null},{"id":"opt_4","text":"성공할 수 있는 기본 조건은 만 시간을 투자하는 것이다.","imageReference":null}],"blanks":[]}' AS JSON), '4', CAST('{"schemaVersion":"answer-spec-v1","questionType":"SINGLE_CHOICE","correctOptionIds":["opt_4"],"correctValue":null,"blanks":[],"scoringPolicyCode":"ALL_OR_NOTHING"}' AS JSON), NULL, 'rl-explanation-strategy-registry-v2', 'MCQ_OPTION_ELIMINATION', 'v1', 2.00, 37, NULL),
    (@lset, (SELECT id FROM practice_question_groups WHERE set_id=@lset AND group_label='L39_40' LIMIT 1), 39, 'SINGLE_CHOICE', '이 대화 앞의 내용으로 알맞은 것을 고르십시오.', CAST('["세계적으로 곡물 배분의 불균형 문제가 심각하다.","세계 곡물 생산량 중 많은 양이 가축 먹이로 소비된다.","곡물 시장에서는 몇몇 국가들의 주도로 가격이 결정된다.","곡물을 먹고 자란 소들은 식물을 먹고 자란 소보다 빨리 자란다."]' AS JSON), CAST('{"schemaVersion":"question-content-v3","languageTag":"ko","options":[{"id":"opt_1","text":"세계적으로 곡물 배분의 불균형 문제가 심각하다.","imageReference":null},{"id":"opt_2","text":"세계 곡물 생산량 중 많은 양이 가축 먹이로 소비된다.","imageReference":null},{"id":"opt_3","text":"곡물 시장에서는 몇몇 국가들의 주도로 가격이 결정된다.","imageReference":null},{"id":"opt_4","text":"곡물을 먹고 자란 소들은 식물을 먹고 자란 소보다 빨리 자란다.","imageReference":null}],"blanks":[]}' AS JSON), '2', CAST('{"schemaVersion":"answer-spec-v1","questionType":"SINGLE_CHOICE","correctOptionIds":["opt_2"],"correctValue":null,"blanks":[],"scoringPolicyCode":"ALL_OR_NOTHING"}' AS JSON), NULL, 'rl-explanation-strategy-registry-v2', 'MCQ_OPTION_ELIMINATION', 'v1', 2.00, 38, NULL),
    (@lset, (SELECT id FROM practice_question_groups WHERE set_id=@lset AND group_label='L39_40' LIMIT 1), 40, 'SINGLE_CHOICE', '들은 내용과 일치하는 것을 고르십시오.', CAST('["곡물상들은 이윤을 위해 곡물을 대량 구매한다.","곡물 가격이 오르면 국제기구가 시장에 개입한다.","국제기구는 식량을 구입하여 가난한 나라에 싸게 공급한다.","가축 사료로 소비되는 곡물 양 때문에 곡물 가격이 내려간다."]' AS JSON), CAST('{"schemaVersion":"question-content-v3","languageTag":"ko","options":[{"id":"opt_1","text":"곡물상들은 이윤을 위해 곡물을 대량 구매한다.","imageReference":null},{"id":"opt_2","text":"곡물 가격이 오르면 국제기구가 시장에 개입한다.","imageReference":null},{"id":"opt_3","text":"국제기구는 식량을 구입하여 가난한 나라에 싸게 공급한다.","imageReference":null},{"id":"opt_4","text":"가축 사료로 소비되는 곡물 양 때문에 곡물 가격이 내려간다.","imageReference":null}],"blanks":[]}' AS JSON), '1', CAST('{"schemaVersion":"answer-spec-v1","questionType":"SINGLE_CHOICE","correctOptionIds":["opt_1"],"correctValue":null,"blanks":[],"scoringPolicyCode":"ALL_OR_NOTHING"}' AS JSON), NULL, 'rl-explanation-strategy-registry-v2', 'MCQ_OPTION_ELIMINATION', 'v1', 2.00, 39, NULL),
    (@lset, (SELECT id FROM practice_question_groups WHERE set_id=@lset AND group_label='L41_42' LIMIT 1), 41, 'SINGLE_CHOICE', '들은 내용과 일치하는 것을 고르십시오.', CAST('["원숭이는 복잡한 동작을 따라 할 수 있다.","아기들은 거울 세포를 아직 가지고 있지 않다.","인간은 직접 경험하지 않아도 지식을 습득할 수 있다.","인간은 책에서 읽은 것을 행동으로 따라 하면서 이해한다."]' AS JSON), CAST('{"schemaVersion":"question-content-v3","languageTag":"ko","options":[{"id":"opt_1","text":"원숭이는 복잡한 동작을 따라 할 수 있다.","imageReference":null},{"id":"opt_2","text":"아기들은 거울 세포를 아직 가지고 있지 않다.","imageReference":null},{"id":"opt_3","text":"인간은 직접 경험하지 않아도 지식을 습득할 수 있다.","imageReference":null},{"id":"opt_4","text":"인간은 책에서 읽은 것을 행동으로 따라 하면서 이해한다.","imageReference":null}],"blanks":[]}' AS JSON), '3', CAST('{"schemaVersion":"answer-spec-v1","questionType":"SINGLE_CHOICE","correctOptionIds":["opt_3"],"correctValue":null,"blanks":[],"scoringPolicyCode":"ALL_OR_NOTHING"}' AS JSON), NULL, 'rl-explanation-strategy-registry-v2', 'MCQ_OPTION_ELIMINATION', 'v1', 2.00, 40, NULL),
    (@lset, (SELECT id FROM practice_question_groups WHERE set_id=@lset AND group_label='L41_42' LIMIT 1), 42, 'SINGLE_CHOICE', '남자의 중심 생각으로 맞는 것을 고르십시오.', CAST('["원숭이는 인간보다 모방 능력이 떨어진다.","인간은 모방을 통해서 새로운 지식을 학습한다.","인간은 거울 세포를 통해 문화를 발달시킬 수 있다.","다른 사람을 따라 할 때 뇌 속의 거울 세포가 작용한다."]' AS JSON), CAST('{"schemaVersion":"question-content-v3","languageTag":"ko","options":[{"id":"opt_1","text":"원숭이는 인간보다 모방 능력이 떨어진다.","imageReference":null},{"id":"opt_2","text":"인간은 모방을 통해서 새로운 지식을 학습한다.","imageReference":null},{"id":"opt_3","text":"인간은 거울 세포를 통해 문화를 발달시킬 수 있다.","imageReference":null},{"id":"opt_4","text":"다른 사람을 따라 할 때 뇌 속의 거울 세포가 작용한다.","imageReference":null}],"blanks":[]}' AS JSON), '3', CAST('{"schemaVersion":"answer-spec-v1","questionType":"SINGLE_CHOICE","correctOptionIds":["opt_3"],"correctValue":null,"blanks":[],"scoringPolicyCode":"ALL_OR_NOTHING"}' AS JSON), NULL, 'rl-explanation-strategy-registry-v2', 'MCQ_OPTION_ELIMINATION', 'v1', 2.00, 41, NULL),
    (@lset, (SELECT id FROM practice_question_groups WHERE set_id=@lset AND group_label='L43_44' LIMIT 1), 43, 'SINGLE_CHOICE', '겨울철 둠벙에 물이 없는 이유로 맞는 것을 고르십시오.', CAST('["벼농사를 짓지 않기 때문에","습지 동식물들이 사라졌기 때문에","농사를 지을 때 물이 많이 필요하기 때문에","물이 없어야 둠벙의 기능을 제대로 할 수 있기 때문에"]' AS JSON), CAST('{"schemaVersion":"question-content-v3","languageTag":"ko","options":[{"id":"opt_1","text":"벼농사를 짓지 않기 때문에","imageReference":null},{"id":"opt_2","text":"습지 동식물들이 사라졌기 때문에","imageReference":null},{"id":"opt_3","text":"농사를 지을 때 물이 많이 필요하기 때문에","imageReference":null},{"id":"opt_4","text":"물이 없어야 둠벙의 기능을 제대로 할 수 있기 때문에","imageReference":null}],"blanks":[]}' AS JSON), '1', CAST('{"schemaVersion":"answer-spec-v1","questionType":"SINGLE_CHOICE","correctOptionIds":["opt_1"],"correctValue":null,"blanks":[],"scoringPolicyCode":"ALL_OR_NOTHING"}' AS JSON), NULL, 'rl-explanation-strategy-registry-v2', 'MCQ_OPTION_ELIMINATION', 'v1', 2.00, 42, NULL),
    (@lset, (SELECT id FROM practice_question_groups WHERE set_id=@lset AND group_label='L43_44' LIMIT 1), 44, 'SINGLE_CHOICE', '이 이야기의 중심 내용으로 맞는 것을 고르십시오.', CAST('["둠벙은 농사를 위해 물을 채워야 한다.","둠벙은 인위적으로 빈 상태를 유지한다.","둠벙은 습지 동식물의 소중한 생활공간이다.","둠벙은 논에 물을 공급하기 위해 만든 웅덩이이다."]' AS JSON), CAST('{"schemaVersion":"question-content-v3","languageTag":"ko","options":[{"id":"opt_1","text":"둠벙은 농사를 위해 물을 채워야 한다.","imageReference":null},{"id":"opt_2","text":"둠벙은 인위적으로 빈 상태를 유지한다.","imageReference":null},{"id":"opt_3","text":"둠벙은 습지 동식물의 소중한 생활공간이다.","imageReference":null},{"id":"opt_4","text":"둠벙은 논에 물을 공급하기 위해 만든 웅덩이이다.","imageReference":null}],"blanks":[]}' AS JSON), '3', CAST('{"schemaVersion":"answer-spec-v1","questionType":"SINGLE_CHOICE","correctOptionIds":["opt_3"],"correctValue":null,"blanks":[],"scoringPolicyCode":"ALL_OR_NOTHING"}' AS JSON), NULL, 'rl-explanation-strategy-registry-v2', 'MCQ_OPTION_ELIMINATION', 'v1', 2.00, 43, NULL),
    (@lset, (SELECT id FROM practice_question_groups WHERE set_id=@lset AND group_label='L45_46' LIMIT 1), 45, 'SINGLE_CHOICE', '들은 내용과 일치하는 것을 고르십시오.', CAST('["‘팝페라’는 익숙한 느낌 때문에 신선하지 않다.","두 장르가 만나서 생겨난 음악은 이해하기 어렵다.","‘콜라보레이션’은 다름을 인정하고 조화를 추구한다.","지금은 ‘같음’과 ‘다름’이라는 이분법적 사고가 필요한 때이다."]' AS JSON), CAST('{"schemaVersion":"question-content-v3","languageTag":"ko","options":[{"id":"opt_1","text":"‘팝페라’는 익숙한 느낌 때문에 신선하지 않다.","imageReference":null},{"id":"opt_2","text":"두 장르가 만나서 생겨난 음악은 이해하기 어렵다.","imageReference":null},{"id":"opt_3","text":"‘콜라보레이션’은 다름을 인정하고 조화를 추구한다.","imageReference":null},{"id":"opt_4","text":"지금은 ‘같음’과 ‘다름’이라는 이분법적 사고가 필요한 때이다.","imageReference":null}],"blanks":[]}' AS JSON), '3', CAST('{"schemaVersion":"answer-spec-v1","questionType":"SINGLE_CHOICE","correctOptionIds":["opt_3"],"correctValue":null,"blanks":[],"scoringPolicyCode":"ALL_OR_NOTHING"}' AS JSON), NULL, 'rl-explanation-strategy-registry-v2', 'MCQ_OPTION_ELIMINATION', 'v1', 2.00, 44, NULL),
    (@lset, (SELECT id FROM practice_question_groups WHERE set_id=@lset AND group_label='L45_46' LIMIT 1), 46, 'SINGLE_CHOICE', '여자의 태도로 가장 알맞은 것을 고르십시오.', CAST('["구체적인 사례에서 결론을 유도하고 있다.","기준을 제시하면서 내용을 분류하고 있다.","예리한 관찰을 통해 현상을 분석하고 있다.","안정된 논리로 자신의 청중을 설득하고 있다."]' AS JSON), CAST('{"schemaVersion":"question-content-v3","languageTag":"ko","options":[{"id":"opt_1","text":"구체적인 사례에서 결론을 유도하고 있다.","imageReference":null},{"id":"opt_2","text":"기준을 제시하면서 내용을 분류하고 있다.","imageReference":null},{"id":"opt_3","text":"예리한 관찰을 통해 현상을 분석하고 있다.","imageReference":null},{"id":"opt_4","text":"안정된 논리로 자신의 청중을 설득하고 있다.","imageReference":null}],"blanks":[]}' AS JSON), '1', CAST('{"schemaVersion":"answer-spec-v1","questionType":"SINGLE_CHOICE","correctOptionIds":["opt_1"],"correctValue":null,"blanks":[],"scoringPolicyCode":"ALL_OR_NOTHING"}' AS JSON), NULL, 'rl-explanation-strategy-registry-v2', 'MCQ_OPTION_ELIMINATION', 'v1', 2.00, 45, NULL),
    (@lset, (SELECT id FROM practice_question_groups WHERE set_id=@lset AND group_label='L47_48' LIMIT 1), 47, 'SINGLE_CHOICE', '들은 내용과 일치하는 것을 고르십시오.', CAST('["의료 서비스 산업의 발전에는 투자가 중요하다.","의료 서비스 산업의 국가 경쟁력이 높은 편이다.","의료 서비스 산업을 위한 제도 정착이 불가능하다.","의료 서비스 산업을 위한 비영리기관의 설립이 시급하다."]' AS JSON), CAST('{"schemaVersion":"question-content-v3","languageTag":"ko","options":[{"id":"opt_1","text":"의료 서비스 산업의 발전에는 투자가 중요하다.","imageReference":null},{"id":"opt_2","text":"의료 서비스 산업의 국가 경쟁력이 높은 편이다.","imageReference":null},{"id":"opt_3","text":"의료 서비스 산업을 위한 제도 정착이 불가능하다.","imageReference":null},{"id":"opt_4","text":"의료 서비스 산업을 위한 비영리기관의 설립이 시급하다.","imageReference":null}],"blanks":[]}' AS JSON), '1', CAST('{"schemaVersion":"answer-spec-v1","questionType":"SINGLE_CHOICE","correctOptionIds":["opt_1"],"correctValue":null,"blanks":[],"scoringPolicyCode":"ALL_OR_NOTHING"}' AS JSON), NULL, 'rl-explanation-strategy-registry-v2', 'MCQ_OPTION_ELIMINATION', 'v1', 2.00, 46, NULL),
    (@lset, (SELECT id FROM practice_question_groups WHERE set_id=@lset AND group_label='L47_48' LIMIT 1), 48, 'SINGLE_CHOICE', '남자의 태도로 가장 알맞은 것을 고르십시오.', CAST('["국내 병원의 해외 진출 부작용을 설명하고 있다.","의료 산업의 현 위치와 문제점을 진단하고 있다.","현재 선진국 의료 산업 현황에 우려를 나타내고 있다.","의사의 국제 경쟁력을 높이기 위한 법 제정을 촉구하고 있다."]' AS JSON), CAST('{"schemaVersion":"question-content-v3","languageTag":"ko","options":[{"id":"opt_1","text":"국내 병원의 해외 진출 부작용을 설명하고 있다.","imageReference":null},{"id":"opt_2","text":"의료 산업의 현 위치와 문제점을 진단하고 있다.","imageReference":null},{"id":"opt_3","text":"현재 선진국 의료 산업 현황에 우려를 나타내고 있다.","imageReference":null},{"id":"opt_4","text":"의사의 국제 경쟁력을 높이기 위한 법 제정을 촉구하고 있다.","imageReference":null}],"blanks":[]}' AS JSON), '2', CAST('{"schemaVersion":"answer-spec-v1","questionType":"SINGLE_CHOICE","correctOptionIds":["opt_2"],"correctValue":null,"blanks":[],"scoringPolicyCode":"ALL_OR_NOTHING"}' AS JSON), NULL, 'rl-explanation-strategy-registry-v2', 'MCQ_OPTION_ELIMINATION', 'v1', 2.00, 47, NULL),
    (@lset, (SELECT id FROM practice_question_groups WHERE set_id=@lset AND group_label='L49_50' LIMIT 1), 49, 'SINGLE_CHOICE', '들은 내용과 일치하는 것을 고르십시오.', CAST('["물 산업 발전을 위해 신기술을 수입해야 한다.","물 산업 육성을 위한 하수 처리 기술 개발이 부족하다.","물 산업 육성을 위해 체계적인 기술 수입 방안이 논의되어야 한다.","물 산업 발전을 위한 효과적인 방법은 물 관련 기관들의 협력이다."]' AS JSON), CAST('{"schemaVersion":"question-content-v3","languageTag":"ko","options":[{"id":"opt_1","text":"물 산업 발전을 위해 신기술을 수입해야 한다.","imageReference":null},{"id":"opt_2","text":"물 산업 육성을 위한 하수 처리 기술 개발이 부족하다.","imageReference":null},{"id":"opt_3","text":"물 산업 육성을 위해 체계적인 기술 수입 방안이 논의되어야 한다.","imageReference":null},{"id":"opt_4","text":"물 산업 발전을 위한 효과적인 방법은 물 관련 기관들의 협력이다.","imageReference":null}],"blanks":[]}' AS JSON), '4', CAST('{"schemaVersion":"answer-spec-v1","questionType":"SINGLE_CHOICE","correctOptionIds":["opt_4"],"correctValue":null,"blanks":[],"scoringPolicyCode":"ALL_OR_NOTHING"}' AS JSON), NULL, 'rl-explanation-strategy-registry-v2', 'MCQ_OPTION_ELIMINATION', 'v1', 2.00, 48, NULL),
    (@lset, (SELECT id FROM practice_question_groups WHERE set_id=@lset AND group_label='L49_50' LIMIT 1), 50, 'SINGLE_CHOICE', '여자의 태도로 가장 알맞은 것을 고르십시오.', CAST('["물 산업 정책의 사례를 설명하며 비판하고 있다.","물 산업 정책의 결과를 분석하며 반성하고 있다.","물 부족 현상을 지적하며 그 대비책을 제안하고 있다.","물 부족 현상의 원인 규명을 강력하게 촉구하고 있다."]' AS JSON), CAST('{"schemaVersion":"question-content-v3","languageTag":"ko","options":[{"id":"opt_1","text":"물 산업 정책의 사례를 설명하며 비판하고 있다.","imageReference":null},{"id":"opt_2","text":"물 산업 정책의 결과를 분석하며 반성하고 있다.","imageReference":null},{"id":"opt_3","text":"물 부족 현상을 지적하며 그 대비책을 제안하고 있다.","imageReference":null},{"id":"opt_4","text":"물 부족 현상의 원인 규명을 강력하게 촉구하고 있다.","imageReference":null}],"blanks":[]}' AS JSON), '3', CAST('{"schemaVersion":"answer-spec-v1","questionType":"SINGLE_CHOICE","correctOptionIds":["opt_3"],"correctValue":null,"blanks":[],"scoringPolicyCode":"ALL_OR_NOTHING"}' AS JSON), NULL, 'rl-explanation-strategy-registry-v2', 'MCQ_OPTION_ELIMINATION', 'v1', 2.00, 49, NULL);
